```zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "llm-train",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    exe.addIncludePath(.{ .cwd_relative = "kernels/cuda" });
    exe.addIncludePath(.{ .cwd_relative = "/usr/local/cuda/include" });
    exe.addLibraryPath(.{ .cwd_relative = "/usr/local/cuda/lib64" });
    exe.addLibraryPath(.{ .cwd_relative = "kernels/cuda/build" });

    exe.linkSystemLibrary("cuda");
    exe.linkSystemLibrary("cudart");
    exe.linkSystemLibrary("nccl");
    exe.linkSystemLibrary("stdc++");
    exe.linkLibC();

    const kernels_lib = b.addStaticLibrary(.{
        .name = "kernels",
        .target = target,
        .optimize = optimize,
    });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/gemm_sm100.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/rms_norm.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/gelu.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/short_conv.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/outer_product.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/scan.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/newton_schulz.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/efla_update.o" });
    kernels_lib.addObjectFile(.{ .cwd_relative = "kernels/cuda/build/prism_update.o" });
    exe.linkLibrary(kernels_lib);

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run llm-train");
    run_step.dependOn(&run_cmd.step);

    const tensor_tests = b.addTest(.{
        .root_source_file = b.path("tests/unit/tensor_test.zig"),
        .target = target,
        .optimize = optimize,
    });
    tensor_tests.addIncludePath(.{ .cwd_relative = "kernels/cuda" });
    tensor_tests.addIncludePath(.{ .cwd_relative = "/usr/local/cuda/include" });
    tensor_tests.addLibraryPath(.{ .cwd_relative = "/usr/local/cuda/lib64" });
    tensor_tests.linkSystemLibrary("cudart");
    tensor_tests.linkLibC();

    const config_tests = b.addTest(.{
        .root_source_file = b.path("tests/unit/config_test.zig"),
        .target = target,
        .optimize = optimize,
    });

    const rng_tests = b.addTest(.{
        .root_source_file = b.path("tests/unit/rng_test.zig"),
        .target = target,
        .optimize = optimize,
    });

    const run_tensor_tests = b.addRunArtifact(tensor_tests);
    const run_config_tests = b.addRunArtifact(config_tests);
    const run_rng_tests = b.addRunArtifact(rng_tests);

    const test_step = b.step("test", "Run all unit tests");
    test_step.dependOn(&run_tensor_tests.step);
    test_step.dependOn(&run_config_tests.step);
    test_step.dependOn(&run_rng_tests.step);
}
