path: src/main.zig

```zig
const std = @import("std");
const distributed = @import("runtime/distributed.zig");
const lm = @import("model/lm.zig");
const lion_mod = @import("optim/lion.zig");
const muon_mod = @import("optim/muon.zig");
const scheduler_mod = @import("optim/scheduler.zig");
const state_shard_mod = @import("optim/state_shard.zig");
const dataset_mod = @import("data/dataset.zig");
const packing_mod = @import("data/packing.zig");
const tokenizer_mod = @import("data/tokenizer.zig");
const bpe_mod = @import("data/bpe.zig");
const writer_mod = @import("checkpoint/writer.zig");
const reader_mod = @import("checkpoint/reader.zig");
const integrity_mod = @import("checkpoint/integrity.zig");
const perplexity_mod = @import("eval/perplexity.zig");
const generation_mod = @import("eval/generation.zig");
const metrics_mod = @import("telemetry/metrics.zig");
const logger_mod = @import("telemetry/logger.zig");
const health_mod = @import("telemetry/health.zig");
const config_mod = @import("util/config.zig");
const error_mod = @import("util/error.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{ .safety = true }){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    if (args.len < 2) {
        try printUsage(allocator);
        std.process.exit(1);
    }

    const command = args[1];

    if (std.mem.eql(u8, command, "train")) {
        try cmdTrain(allocator, args[2..]);
    } else if (std.mem.eql(u8, command, "tokenizer")) {
        try cmdTokenizer(allocator, args[2..]);
    } else if (std.mem.eql(u8, command, "eval")) {
        try cmdEval(allocator, args[2..]);
    } else if (std.mem.eql(u8, command, "--version")) {
        const stdout = std.io.getStdOut().writer();
        try stdout.print("llm-train v0.1.0 (CUDA SM100, Zig 0.13)\n", .{});
    } else {
        try printUsage(allocator);
        std.process.exit(1);
    }
}

fn printUsage(allocator: std.mem.Allocator) !void {
    _ = allocator;
    const stdout = std.io.getStdOut().writer();
    try stdout.writeAll(
        "Usage: llm-train <command> [options]\n" ++
        "Commands:\n" ++
        "  train      --config <path> --data-path <path> --checkpoint-dir <path> --gpus <list> [--resume <ckpt>]\n" ++
        "  tokenizer  train|encode|decode [options]\n" ++
        "  eval       --model <ckpt> --data-path <path>\n" ++
        "  --version\n",
    );
}

fn cmdTrain(allocator: std.mem.Allocator, args: [][]const u8) !void {
    var config_path: ?[]const u8 = null;
    var data_path: ?[]const u8 = null;
    var checkpoint_dir: []const u8 = "./checkpoints";
    var resume_path: ?[]const u8 = null;
    var gpu_ids_str: []const u8 = "0,1,2,3,4,5,6,7";
    var max_steps: u32 = 0;

    var i: usize = 0;
    while (i < args.len) : (i += 1) {
        if (std.mem.eql(u8, args[i], "--config") and i + 1 < args.len) {
            i += 1;
            config_path = args[i];
        } else if (std.mem.eql(u8, args[i], "--data-path") and i + 1 < args.len) {
            i += 1;
            data_path = args[i];
        } else if (std.mem.eql(u8, args[i], "--checkpoint-dir") and i + 1 < args.len) {
            i += 1;
            checkpoint_dir = args[i];
        } else if (std.mem.eql(u8, args[i], "--resume") and i + 1 < args.len) {
            i += 1;
            resume_path = args[i];
        } else if (std.mem.eql(u8, args[i], "--gpus") and i + 1 < args.len) {
            i += 1;
            gpu_ids_str = args[i];
        } else if (std.mem.eql(u8, args[i], "--steps") and i + 1 < args.len) {
            i += 1;
            max_steps = try std.fmt.parseInt(u32, args[i], 10);
        }
    }

    if (data_path == null) {
        std.debug.print("Error: --data-path is required\n", .{});
        std.process.exit(1);
    }

    var gpu_list = std.ArrayList(u32).init(allocator);
    defer gpu_list.deinit();
    var it = std.mem.splitScalar(u8, gpu_ids_str, ',');
    while (it.next()) |tok| {
        const id = try std.fmt.parseInt(u32, std.mem.trim(u8, tok, " \t"), 10);
        try gpu_list.append(id);
    }

    const model_cfg = try config_mod.loadModelConfig(allocator, config_path);
    const train_cfg = try config_mod.loadTrainingConfig(allocator, config_path);
    const cluster_cfg = try config_mod.loadClusterConfig(allocator, config_path);

    var dist = try distributed.DistributedRuntime.init(allocator, gpu_list.items, cluster_cfg);
    defer dist.deinit();

    const rank = dist.rank;
    const world_size = dist.world_size;

    var logger = try logger_mod.Logger.init(allocator, rank);
    defer logger.deinit();

    try logger.logInfo("rank={} world={} gpus={}", .{ rank, world_size, gpu_list.items.len });

    var language_model = try lm.LanguageModel.init(allocator, model_cfg, &dist);
    defer language_model.deinit();

    var lion = try lion_mod.Lion.init(allocator, train_cfg.lion_lr, train_cfg.lion_beta1, train_cfg.lion_beta2, train_cfg.lion_weight_decay);
    defer lion.deinit();

    var muon = try muon_mod.Muon.init(allocator, train_cfg.muon_lr, train_cfg.muon_momentum, train_cfg.muon_ns_iters);
    defer muon.deinit();

    var sched = scheduler_mod.CosineScheduler.init(train_cfg.lr_warmup_steps, train_cfg.lr_decay_steps, train_cfg.lr_max, train_cfg.lr_min);

    var shard_state = try state_shard_mod.OptimizerStateShard.init(allocator, rank, world_size);
    defer shard_state.deinit();

    var dataset = try dataset_mod.TokenDataset.open(allocator, data_path.?);
    defer dataset.close();

    var packer = try packing_mod.SequencePacker.init(allocator, model_cfg.max_seq_len, train_cfg.shuffle_seed, rank, world_size);
    defer packer.deinit();

    var health = health_mod.HealthMonitor.init(train_cfg.fp8_amax_history);
    var metrics = metrics_mod.Metrics.init();

    var start_step: u32 = 0;

    if (resume_path) |rpath| {
        try reader_mod.loadCheckpoint(allocator, rpath, &language_model, &lion, &muon, &packer, &start_step);
        try logger.logInfo("Resumed from step {}", .{start_step});
    }

    try std.fs.makeDirAbsolute(checkpoint_dir) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };

    const effective_max_steps = if (max_steps > 0) max_steps else train_cfg.max_steps;

    var step: u32 = start_step;
    while (step < effective_max_steps) : (step += 1) {
        const lr = sched.getLR(step);
        lion.setLR(lr);
        muon.setLR(lr);

        const batch = try packer.nextBatch(allocator, &dataset);
        defer batch.deinit(allocator);

        const forward_result = try language_model.forwardBackward(allocator, batch.tokens, batch.targets, train_cfg.label_smoothing);

        if (health.detectNaN(forward_result.loss)) {
            try logger.logError("NaN detected at step {}, skipping", .{step});
            health.adjustScaling();
            continue;
        }

        try language_model.clipGradients(train_cfg.grad_clip_norm);

        try language_model.optimizerStep(allocator, &lion, &muon, &shard_state, &dist);

        try dist.synchronizeBarrier();

        metrics.update(step, forward_result.loss, lr, forward_result.tokens_processed, forward_result.grad_norm);

        if (step % train_cfg.log_interval == 0) {
            try logger.logStep(metrics);
        }

        if (step % train_cfg.checkpoint_interval == 0 and step > start_step) {
            const ckpt_path = try std.fmt.allocPrint(allocator, "{s}/step_{}", .{ checkpoint_dir, step });
            defer allocator.free(ckpt_path);
            try writer_mod.saveCheckpoint(allocator, ckpt_path, &language_model, &lion, &muon, &packer, step);
            try logger.logInfo("Checkpoint saved: {s}", .{ckpt_path});
        }

        if (step % train_cfg.eval_interval == 0 and step > start_step) {
            const ppl = try perplexity_mod.evaluate(allocator, &language_model, data_path.?, 1000);
            try logger.logInfo("step={} perplexity={d:.4}", .{ step, ppl });
        }
    }

    const final_ckpt = try std.fmt.allocPrint(allocator, "{s}/final_step_{}", .{ checkpoint_dir, effective_max_steps });
    defer allocator.free(final_ckpt);
    try writer_mod.saveCheckpoint(allocator, final_ckpt, &language_model, &lion, &muon, &packer, effective_max_steps);
    try logger.logInfo("Training complete. Final checkpoint: {s}", .{final_ckpt});
}

fn cmdTokenizer(allocator: std.mem.Allocator, args: [][]const u8) !void {
    if (args.len < 1) {
        std.debug.print("Usage: llm-train tokenizer train|encode|decode [options]\n", .{});
        std.process.exit(1);
    }
    const sub = args[0];
    if (std.mem.eql(u8, sub, "train")) {
        var corpus_path: ?[]const u8 = null;
        var vocab_size: u32 = 50000;
        var output_path: []const u8 = "tokenizer.model";
        var i: usize = 1;
        while (i < args.len) : (i += 1) {
            if (std.mem.eql(u8, args[i], "--corpus") and i + 1 < args.len) {
                i += 1;
                corpus_path = args[i];
            } else if (std.mem.eql(u8, args[i], "--vocab-size") and i + 1 < args.len) {
                i += 1;
                vocab_size = try std.fmt.parseInt(u32, args[i], 10);
            } else if (std.mem.eql(u8, args[i], "--output") and i + 1 < args.len) {
                i += 1;
                output_path = args[i];
            }
        }
        if (corpus_path == null) {
            std.debug.print("Error: --corpus required\n", .{});
            std.process.exit(1);
        }
        var bpe = try bpe_mod.BPETrainer.init(allocator, vocab_size);
        defer bpe.deinit();
        try bpe.trainFromFile(corpus_path.?);
        try bpe.saveModel(output_path);
        std.debug.print("Tokenizer saved to {s}\n", .{output_path});
    } else if (std.mem.eql(u8, sub, "encode")) {
        var model_path: ?[]const u8 = null;
        var input_path: ?[]const u8 = null;
        var output_path: ?[]const u8 = null;
        var i: usize = 1;
        while (i < args.len) : (i += 1) {
            if (std.mem.eql(u8, args[i], "--model") and i + 1 < args.len) {
                i += 1;
                model_path = args[i];
            } else if (std.mem.eql(u8, args[i], "--input") and i + 1 < args.len) {
                i += 1;
                input_path = args[i];
            } else if (std.mem.eql(u8, args[i], "--output") and i + 1 < args.len) {
                i += 1;
                output_path = args[i];
            }
        }
        if (model_path == null or input_path == null or output_path == null) {
            std.debug.print("Error: --model, --input, --output required\n", .{});
            std.process.exit(1);
        }
        var tok = try tokenizer_mod.Tokenizer.loadModel(allocator, model_path.?);
        defer tok.deinit();
        try tok.encodeFile(input_path.?, output_path.?);
    } else if (std.mem.eql(u8, sub, "decode")) {
        var model_path: ?[]const u8 = null;
        var input_path: ?[]const u8 = null;
        var output_path: ?[]const u8 = null;
        var i: usize = 1;
        while (i < args.len) : (i += 1) {
            if (std.mem.eql(u8, args[i], "--model") and i + 1 < args.len) {
                i += 1;
                model_path = args[i];
            } else if (std.mem.eql(u8, args[i], "--input") and i + 1 < args.len) {
                i += 1;
                input_path = args[i];
            } else if (std.mem.eql(u8, args[i], "--output") and i + 1 < args.len) {
                i += 1;
                output_path = args[i];
            }
        }
        if (model_path == null or input_path == null or output_path == null) {
            std.debug.print("Error: --model, --input, --output required\n", .{});
            std.process.exit(1);
        }
        var tok = try tokenizer_mod.Tokenizer.loadModel(allocator, model_path.?);
        defer tok.deinit();
        try tok.decodeFile(input_path.?, output_path.?);
    } else {
        std.debug.print("Unknown tokenizer subcommand: {s}\n", .{sub});
        std.process.exit(1);
    }
}

fn cmdEval(allocator: std.mem.Allocator, args: [][]const u8) !void {
    var model_path: ?[]const u8 = null;
    var data_path: ?[]const u8 = null;
    var num_tokens: u32 = 10000;
    var i: usize = 0;
    while (i < args.len) : (i += 1) {
        if (std.mem.eql(u8, args[i], "--model") and i + 1 < args.len) {
            i += 1;
            model_path = args[i];
        } else if (std.mem.eql(u8, args[i], "--data-path") and i + 1 < args.len) {
            i += 1;
            data_path = args[i];
        } else if (std.mem.eql(u8, args[i], "--num-tokens") and i + 1 < args.len) {
            i += 1;
            num_tokens = try std.fmt.parseInt(u32, args[i], 10);
        }
    }
    if (model_path == null or data_path == null) {
        std.debug.print("Error: --model and --data-path required\n", .{});
        std.process.exit(1);
    }
    const dummy_gpus = [_]u32{0};
    const cluster_cfg = config_mod.ClusterConfig{};
    var dist = try distributed.DistributedRuntime.init(allocator, &dummy_gpus, cluster_cfg);
    defer dist.deinit();
    const model_cfg = try config_mod.loadModelConfig(allocator, null);
    var language_model = try lm.LanguageModel.init(allocator, model_cfg, &dist);
    defer language_model.deinit();
    var dummy_lion = try lion_mod.Lion.init(allocator, 0.0, 0.9, 0.99, 0.0);
