const std = @import("std");

pub fn writeAllAtomic(dir_path: []const u8, filename: []const u8, data: []const u8, allocator: std.mem.Allocator) !void {
    const tmp_path = try std.fmt.allocPrint(allocator, "{s}/{s}.tmp", .{ dir_path, filename });
    defer allocator.free(tmp_path);
    const final_path = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir_path, filename });
    defer allocator.free(final_path);

    {
        const file = try std.fs.createFileAbsolute(tmp_path, .{});
        defer file.close();
        try file.writeAll(data);
        try file.sync();
    }

    try std.fs.renameAbsolute(tmp_path, final_path);
}

pub fn readFileAlloc(path: []const u8, allocator: std.mem.Allocator) ![]u8 {
    const file = try std.fs.openFileAbsolute(path, .{});
    defer file.close();
    const size = try file.getEndPos();
    const buf = try allocator.alloc(u8, size);
    const n = try file.readAll(buf);
    if (n != size) {
        allocator.free(buf);
        return error.UnexpectedEOF;
    }
    return buf;
}

pub fn ensureDir(path: []const u8) !void {
    std.fs.makeDirAbsolute(path) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };
