pub const DType = enum(u8) {
    f32 = 0,
    f16 = 1,
    bf16 = 2,
    f8_e4m3 = 3,
    f8_e5m2 = 4,
    i32 = 5,
    u32 = 6,
    i64 = 7,
};

pub fn dtypeSize(dt: DType) usize {
    return switch (dt) {
        .f32 => 4,
        .f16 => 2,
        .bf16 => 2,
        .f8_e4m3 => 1,
        .f8_e5m2 => 1,
        .i32 => 4,
        .u32 => 4,
        .i64 => 8,
    };
}

pub const ScaleMetadata = struct {
    scale: f32,
    amax_history: [16]f32,
    history_len: u32,
    history_idx: u32,

    pub fn init(initial_scale: f32) ScaleMetadata {
        var sm = ScaleMetadata{
            .scale = initial_scale,
            .amax_history = [_]f32{0.0} ** 16,
            .history_len = 16,
            .history_idx = 0,
        };
        return sm;
    }

    pub fn updateAmax(self: *ScaleMetadata, amax: f32) void {
        self.amax_history[self.history_idx % self.history_len] = amax;
        self.history_idx += 1;
    }

    pub fn computeNewScale(self: *const ScaleMetadata, fp8_max: f32) f32 {
        var max_amax: f32 = 0.0;
        for (self.amax_history) |v| {
            if (v > max_amax) max_amax = v;
        }
        if (max_amax == 0.0) return 1.0;
        return fp8_max / max_amax;
    }
};
