const std = @import("std");

pub const Layout = enum {
    row_major,
    col_major,
    blocked,
};

pub const TensorLayout = struct {
    ndim: u32,
    shape: [8]u32,
    strides: [8]u64,
    layout: Layout,

    pub fn init(shape: []const u32, layout: Layout) TensorLayout {
        var tl = TensorLayout{
            .ndim = @intCast(shape.len),
            .shape = [_]u32{0} ** 8,
            .strides = [_]u64{0} ** 8,
            .layout = layout,
        };
        for (shape, 0..) |s, i| tl.shape[i] = s;
        tl.computeStrides(shape);
        return tl;
    }

    fn computeStrides(self: *TensorLayout, shape: []const u32) void {
        if (self.layout == .row_major) {
            var stride: u64 = 1;
            var i: i32 = @intCast(shape.len);
            i -= 1;
            while (i >= 0) : (i -= 1) {
                self.strides[@intCast(i)] = stride;
                stride *= shape[@intCast(i)];
            }
        } else {
            var stride: u64 = 1;
            for (shape, 0..) |s, i| {
                self.strides[i] = stride;
                stride *= s;
            }
        }
    }

    pub fn numElements(self: *const TensorLayout) u64 {
        if (self.ndim == 0) return 0;
        var n: u64 = 1;
        for (0..self.ndim) |i| n *= self.shape[i];
        return n;
    }

    pub fn flatIndex(self: *const TensorLayout, indices: []const u32) u64 {
        var idx: u64 = 0;
        for (indices, 0..) |ind, i| idx += @as(u64, ind) * self.strides[i];
        return idx;
    }
};
