const std = @import("std");
const TensorLayout = @import("layout.zig").TensorLayout;

pub const ShardSpec = struct {
    rank: u32,
    world_size: u32,
    shard_dim: u32,
    shard_start: u32,
    shard_end: u32,
};

pub fn computeShard(full_size: u32, rank: u32, world_size: u32) struct { start: u32, end: u32 } {
    const base = full_size / world_size;
    const rem = full_size % world_size;
    const start = rank * base + @min(rank, rem);
    const end = start + base + @as(u32, if (rank < rem) 1 else 0);
    return .{ .start = start, .end = end };
}

pub fn shardedSize(full_size: u32, rank: u32, world_size: u32) u32 {
    const s = computeShard(full_size, rank, world_size);
    return s.end - s.start;
}

pub fn parameterOwner(param_idx: u64, world_size: u32, total_params: u64) u32 {
    const params_per_rank = total_params / world_size;
    const owner = @min(param_idx / params_per_rank, world_size - 1);
    return @intCast(owner);
}
