const std = @import("std");
const DType = @import("dtype.zig").DType;
const dtypeSize = @import("dtype.zig").dtypeSize;
const TensorLayout = @import("layout.zig").TensorLayout;
const Layout = @import("layout.zig").Layout;
const ScaleMetadata = @import("dtype.zig").ScaleMetadata;

const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    dtype: DType,
    layout: TensorLayout,
    data_gpu: ?*anyopaque,
    data_cpu: ?[]u8,
    num_bytes: usize,
    owns_gpu: bool,
    owns_cpu: bool,
    scale_meta: ?ScaleMetadata,
    grad: ?*Tensor,

    pub fn init(allocator: std.mem.Allocator, shape: []const u32, dtype: DType) !Tensor {
        const tl = TensorLayout.init(shape, .row_major);
        const n = tl.numElements();
        const nb = n * dtypeSize(dtype);

        var gpu_ptr: ?*anyopaque = null;
        if (nb > 0) {
            var raw: ?*anyopaque = null;
            const err = c.cudaMalloc(&raw, nb);
            if (err != 0) return error.CudaError;
            gpu_ptr = raw;
        }

        return Tensor{
            .allocator = allocator,
            .dtype = dtype,
            .layout = tl,
            .data_gpu = gpu_ptr,
            .data_cpu = null,
            .num_bytes = nb,
            .owns_gpu = true,
            .owns_cpu = false,
            .scale_meta = null,
            .grad = null,
        };
    }

    pub fn zeros(allocator: std.mem.Allocator, shape: []const u32, dtype: DType) !Tensor {
        var t = try init(allocator, shape, dtype);
        if (t.data_gpu != null and t.num_bytes > 0) {
            const err = c.cudaMemset(t.data_gpu, 0, t.num_bytes);
            if (err != 0) {
                t.deinit();
                return error.CudaError;
            }
        }
        return t;
    }

    pub fn deinit(self: *Tensor) void {
        if (self.owns_gpu) {
            if (self.data_gpu) |ptr| {
                _ = c.cudaFree(ptr);
                self.data_gpu = null;
            }
        }
        if (self.owns_cpu) {
            if (self.data_cpu) |buf| {
                self.allocator.free(buf);
                self.data_cpu = null;
            }
        }
        if (self.grad) |g| {
            g.deinit();
            self.allocator.destroy(g);
            self.grad = null;
        }
    }

    pub fn numElements(self: *const Tensor) u64 {
        return self.layout.numElements();
    }

    pub fn ndim(self: *const Tensor) u32 {
        return self.layout.ndim;
    }

    pub fn shape(self: *const Tensor) []const u32 {
        return self.layout.shape[0..self.layout.ndim];
    }

    pub fn copyToDevice(self: *Tensor, host_data: []const u8) !void {
        if (host_data.len != self.num_bytes) return error.SizeMismatch;
        if (self.data_gpu == null) return error.NoGPUMemory;
        const err = c.cudaMemcpy(self.data_gpu, host_data.ptr, self.num_bytes, c.cudaMemcpyHostToDevice);
        if (err != 0) return error.CudaError;
    }

    pub fn copyToHost(self: *Tensor, allocator: std.mem.Allocator) ![]u8 {
        const buf = try allocator.alloc(u8, self.num_bytes);
        if (self.data_gpu == null) {
            @memset(buf, 0);
            return buf;
        }
        const err = c.cudaMemcpy(buf.ptr, self.data_gpu, self.num_bytes, c.cudaMemcpyDeviceToHost);
        if (err != 0) {
            allocator.free(buf);
            return error.CudaError;
        }
        return buf;
    }

    pub fn initGrad(self: *Tensor) !void {
        if (self.grad != null) return;
        const g = try self.allocator.create(Tensor);
        g.* = try zeros(self.allocator, self.shape(), self.dtype);
        self.grad = g;
    }

    pub fn zeroGrad(self: *Tensor) !void {
        if (self.grad) |g| {
            if (g.data_gpu != null and g.num_bytes > 0) {
                const err = c.cudaMemset(g.data_gpu, 0, g.num_bytes);
                if (err != 0) return error.CudaError;
            }
        }
    }
};
