const std = @import("std");
const nccl_wrapper = @import("nccl_wrapper.zig");
const process_group = @import("process_group.zig");
const topology = @import("topology.zig");
const config_mod = @import("../util/config.zig");
const error_mod = @import("../util/error.zig");
const Tensor = @import("../tensor/tensor.zig").Tensor;

const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const DistributedRuntime = struct {
    allocator: std.mem.Allocator,
    rank: u32,
    world_size: u32,
    local_rank: u32,
    gpu_id: u32,
    stream: ?*anyopaque,
    comm_stream: ?*anyopaque,
    global_group: process_group.ProcessGroup,
    topo: topology.ProcessTopology,

    pub fn init(
        allocator: std.mem.Allocator,
        gpu_ids: []const u32,
        cluster_cfg: config_mod.ClusterConfig,
    ) !DistributedRuntime {
        const world_size: u32 = @intCast(gpu_ids.len);

        const rank_str = std.posix.getenv("RANK") orelse "0";
        const rank = try std.fmt.parseInt(u32, rank_str, 10);

        if (rank >= world_size) return error.InvalidArgument;

        const gpu_id = gpu_ids[rank];
        const err = c.cudaSetDevice(@intCast(gpu_id));
        try error_mod.cudaCheck(err);

        var stream: ?*anyopaque = null;
        var comm_stream: ?*anyopaque = null;
        const se = c.cudaStreamCreate(@ptrCast(&stream));
        try error_mod.cudaCheck(se);
        const ce = c.cudaStreamCreate(@ptrCast(&comm_stream));
        try error_mod.cudaCheck(ce);

        const uid_str = std.posix.getenv("NCCL_UNIQUE_ID") orelse "";
        var unique_id: nccl_wrapper.NcclUniqueId = undefined;
        if (rank == 0 or uid_str.len == 0) {
            unique_id = try nccl_wrapper.getUniqueId();
        } else {
            @memset(&unique_id.internal, 0);
            const copy_len = @min(uid_str.len, unique_id.internal.len);
            @memcpy(unique_id.internal[0..copy_len], uid_str[0..copy_len]);
        }

        var all_ranks = try allocator.alloc(u32, world_size);
        defer allocator.free(all_ranks);
        for (0..world_size) |i| all_ranks[i] = @intCast(i);

        const pg = try process_group.ProcessGroup.init(allocator, all_ranks, rank, unique_id, stream);
        const proc_topo = topology.ProcessTopology.init(rank, world_size, cluster_cfg.num_gpus);

        _ = cluster_cfg;

        return DistributedRuntime{
            .allocator = allocator,
            .rank = rank,
            .world_size = world_size,
            .local_rank = rank,
            .gpu_id = gpu_id,
            .stream = stream,
            .comm_stream = comm_stream,
            .global_group = pg,
            .topo = proc_topo,
        };
    }

    pub fn deinit(self: *DistributedRuntime) void {
        self.global_group.deinit();
        if (self.stream) |s| _ = c.cudaStreamDestroy(@ptrCast(s));
        if (self.comm_stream) |s| _ = c.cudaStreamDestroy(@ptrCast(s));
    }

    pub fn synchronizeBarrier(self: *DistributedRuntime) !void {
        const err = c.cudaStreamSynchronize(@ptrCast(self.stream));
        try error_mod.cudaCheck(err);
    }

    pub fn allReduceGrad(self: *DistributedRuntime, tensor: *Tensor) !void {
        if (tensor.grad == null) return;
        const g = tensor.grad.?;
        const count = g.numElements();
        try self.global_group.allReduce(g.data_gpu.?, g.data_gpu.?, count, nccl_wrapper.NCCL_FLOAT32);
    }

    pub fn reduceScatterGrad(self: *DistributedRuntime, tensor: *Tensor, recv_buf: *Tensor) !void {
        if (tensor.grad == null) return;
        const g = tensor.grad.?;
        const recv_count = g.numElements() / self.world_size;
        try self.global_group.reduceScatter(g.data_gpu.?, recv_buf.data_gpu.?, recv_count, nccl_wrapper.NCCL_FLOAT32);
    }

    pub fn allGatherParam(self: *DistributedRuntime, shard: *Tensor, full: *Tensor) !void {
        const send_count = shard.numElements();
        try self.global_group.allGather(shard.data_gpu.?, full.data_gpu.?, send_count, nccl_wrapper.NCCL_FLOAT32);
    }
};
