const DType = @import("../tensor/dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Embedding = struct {
    allocator: std.mem.Allocator,
    vocab_size: u32,
    hidden_dim: u32,
    weight: Tensor,
    weight_grad: Tensor,

    pub fn init(allocator: std.mem.Allocator, vocab_size: u32, hidden_dim: u32) !Embedding {
        var weight = try Tensor.init(allocator, &[_]u32{ vocab_size, hidden_dim }, .f32);
        try initEmbeddingWeights(&weight, vocab_size, hidden_dim);
        var weight_grad = try Tensor.zeros(allocator, &[_]u32{ vocab_size, hidden_dim }, .f32);
        return Embedding{
            .allocator = allocator,
            .vocab_size = vocab_size,
            .hidden_dim = hidden_dim,
            .weight = weight,
            .weight_grad = weight_grad,
        };
    }

    pub fn deinit(self: *Embedding) void {
        self.weight.deinit();
        self.weight_grad.deinit();
    }

    fn initEmbeddingWeights(weight: *Tensor, vocab_size: u32, hidden_dim: u32) !void {
        const n = @as(usize, vocab_size) * hidden_dim;
        var host_buf = try weight.allocator.alloc(f32, n);
        defer weight.allocator.free(host_buf);
        var prng = std.rand.DefaultPrng.init(12345);
        const rand = prng.random();
        const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(hidden_dim)));
        for (host_buf) |*v| {
            v.* = (rand.float(f32) * 2.0 - 1.0) * scale;
        }
        const byte_slice = std.mem.sliceAsBytes(host_buf);
        try weight.copyToDevice(byte_slice);
    }

    pub fn forward(self: *Embedding, token_ids: []const u32, seq_len: u32, allocator: std.mem.Allocator) !Tensor {
        var out = try Tensor.zeros(allocator, &[_]u32{ 1, seq_len, self.hidden_dim }, .f32);
        const token_ids_gpu = try allocDeviceU32(token_ids, allocator);
        defer freeDeviceU32(token_ids_gpu);
        c.launch_embedding_lookup(
            self.weight.data_gpu,
            token_ids_gpu,
            out.data_gpu,
            seq_len,
            self.hidden_dim,
            @ptrCast(self.weight.allocator),
        );
        return out;
    }

    pub fn parameters(self: *Embedding) []*Tensor {
        return &[_]*Tensor{&self.weight};
    }
};

fn allocDeviceU32(data: []const u32, allocator: std.mem.Allocator) !*anyopaque {
    _ = allocator;
    var ptr: ?*anyopaque = null;
    const nb = data.len * @sizeOf(u32);
    const c_mod = @cImport(@cInclude("cuda_runtime.h"));
    _ = c_mod.cudaMalloc(&ptr, nb);
    _ = c_mod.cudaMemcpy(ptr, data.ptr, nb, c_mod.cudaMemcpyHostToDevice);
    return ptr.?;
}

fn freeDeviceU32(ptr: *anyopaque) void {
    const c_mod = @cImport(@cInclude("cuda_runtime.h"));
    _ = c_mod.cudaFree(ptr);
}
