const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const RMSNorm = struct {
    allocator: std.mem.Allocator,
    hidden_dim: u32,
    eps: f32,
    weight: Tensor,
    weight_grad: Tensor,
    saved_rms: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, hidden_dim: u32, eps: f32) !RMSNorm {
        var weight = try Tensor.init(allocator, &[_]u32{hidden_dim}, .f32);
        try fillOnes(&weight, hidden_dim, allocator);
        var weight_grad = try Tensor.zeros(allocator, &[_]u32{hidden_dim}, .f32);
        return RMSNorm{
            .allocator = allocator,
            .hidden_dim = hidden_dim,
            .eps = eps,
            .weight = weight,
            .weight_grad = weight_grad,
            .saved_rms = null,
        };
    }

    pub fn deinit(self: *RMSNorm) void {
        self.weight.deinit();
        self.weight_grad.deinit();
        if (self.saved_rms) |*r| r.deinit();
    }

    fn fillOnes(t: *Tensor, n: u32, allocator: std.mem.Allocator) !void {
        var buf = try allocator.alloc(f32, n);
        defer allocator.free(buf);
        @memset(buf, 1.0);
        try t.copyToDevice(std.mem.sliceAsBytes(buf));
    }

    pub fn forward(self: *RMSNorm, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const shape = x.shape();
        const batch = if (shape.len >= 2) shape[0] else 1;
        const seq_len = if (shape.len >= 2) shape[1] else shape[0];
        const hidden = self.hidden_dim;

        var out = try Tensor.zeros(allocator, shape, .f32);

        if (self.saved_rms) |*r| r.deinit();
        const total_tokens = batch * seq_len;
        self.saved_rms = try Tensor.zeros(allocator, &[_]u32{total_tokens}, .f32);

        c.launch_rms_norm(
            @ptrCast(x.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(out.data_gpu),
            @ptrCast(self.saved_rms.?.data_gpu),
            @intCast(batch),
            @intCast(seq_len),
            @intCast(hidden),
            self.eps,
            null,
        );
        return out;
    }

    pub fn backward(self: *RMSNorm, x: *Tensor, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const shape = x.shape();
        const batch = if (shape.len >= 2) shape[0] else 1;
        const seq_len = if (shape.len >= 2) shape[1] else shape[0];
        const hidden = self.hidden_dim;

        var grad_x = try Tensor.zeros(allocator, shape, .f32);

        if (self.saved_rms == null) return error.ForwardNotCalled;

        c.launch_rms_norm_backward(
            @ptrCast(x.data_gpu),
            @ptrCast(grad_out.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(self.saved_rms.?.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @ptrCast(self.weight_grad.data_gpu),
            @intCast(batch),
            @intCast(seq_len),
            @intCast(hidden),
            self.eps,
            null,
        );
        return grad_x;
    }

    pub fn parameters(self: *RMSNorm) [1]*Tensor {
        return [1]*Tensor{&self.weight};
    }

    pub fn gradients(self: *RMSNorm) [1]*Tensor {
        return [1]*Tensor{&self.weight_grad};
    }
};
