const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;
const distributed = @import("../runtime/distributed.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Linear = struct {
    allocator: std.mem.Allocator,
    in_features: u32,
    out_features: u32,
    use_bias: bool,
    weight: Tensor,
    bias: ?Tensor,
    weight_grad: Tensor,
    bias_grad: ?Tensor,
    saved_input: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, in_features: u32, out_features: u32, use_bias: bool) !Linear {
        var weight = try Tensor.init(allocator, &[_]u32{ out_features, in_features }, .f32);
        try kaimingUniformInit(&weight, in_features, allocator);
        var weight_grad = try Tensor.zeros(allocator, &[_]u32{ out_features, in_features }, .f32);

        var bias: ?Tensor = null;
        var bias_grad: ?Tensor = null;
        if (use_bias) {
            bias = try Tensor.zeros(allocator, &[_]u32{out_features}, .f32);
            bias_grad = try Tensor.zeros(allocator, &[_]u32{out_features}, .f32);
        }

        return Linear{
            .allocator = allocator,
            .in_features = in_features,
            .out_features = out_features,
            .use_bias = use_bias,
            .weight = weight,
            .bias = bias,
            .weight_grad = weight_grad,
            .bias_grad = bias_grad,
            .saved_input = null,
        };
    }

    pub fn deinit(self: *Linear) void {
        self.weight.deinit();
        self.weight_grad.deinit();
        if (self.bias) |*b| b.deinit();
        if (self.bias_grad) |*bg| bg.deinit();
        if (self.saved_input) |*si| si.deinit();
    }

    fn kaimingUniformInit(weight: *Tensor, fan_in: u32, allocator: std.mem.Allocator) !void {
        const n = weight.numElements();
        var buf = try allocator.alloc(f32, n);
        defer allocator.free(buf);
        var prng = std.rand.DefaultPrng.init(0xdeadbeef);
        const rand = prng.random();
        const bound = @sqrt(3.0 / @as(f32, @floatFromInt(fan_in)));
        for (buf) |*v| {
            v.* = (rand.float(f32) * 2.0 - 1.0) * bound;
        }
        try weight.copyToDevice(std.mem.sliceAsBytes(buf));
    }

    pub fn forward(self: *Linear, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const shape = x.shape();
        const batch = shape[0];
        const seq_len = if (shape.len >= 3) shape[1] else 1;
        const M: u32 = batch * seq_len;
        const K: u32 = self.in_features;
        const N: u32 = self.out_features;

        if (self.saved_input) |*si| si.deinit();
        self.saved_input = try copyTensor(allocator, x);

        var out = try Tensor.zeros(allocator, if (shape.len >= 3)
            &[_]u32{ batch, seq_len, self.out_features }
        else
            &[_]u32{ batch, self.out_features }, .f32);

        c.launch_gemm_forward(
            @ptrCast(x.data_gpu),
            @ptrCast(self.weight.data_gpu),
            if (self.bias) |*b| @ptrCast(b.data_gpu) else null,
            @ptrCast(out.data_gpu),
            @intCast(M),
            @intCast(N),
            @intCast(K),
            null,
        );
        return out;
    }

    pub fn backward(self: *Linear, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const input = self.saved_input orelse return error.ForwardNotCalled;
        const shape = input.shape();
        const batch = shape[0];
        const seq_len = if (shape.len >= 3) shape[1] else 1;
        const M: u32 = batch * seq_len;
        const K: u32 = self.in_features;
        const N: u32 = self.out_features;

        var grad_x = try Tensor.zeros(allocator, shape, .f32);

        c.launch_gemm_backward(
            @ptrCast(input.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @ptrCast(self.weight_grad.data_gpu),
            if (self.bias_grad) |*bg| @ptrCast(bg.data_gpu) else null,
            @intCast(M),
            @intCast(N),
            @intCast(K),
            null,
        );
        return grad_x;
    }

    pub fn parameters(self: *Linear) []*Tensor {
        if (self.use_bias) {
            return &[_]*Tensor{ &self.weight, &self.bias.? };
        }
        return &[_]*Tensor{&self.weight};
    }
};

fn copyTensor(allocator: std.mem.Allocator, src: *Tensor) !Tensor {
    var dst = try Tensor.init(allocator, src.shape(), src.dtype);
    const c_mod = @cImport(@cInclude("cuda_runtime.h"));
    _ = c_mod.cudaMemcpy(dst.data_gpu, src.data_gpu, src.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
    return dst;
}
