const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;
const Linear = @import("../nn/linear.zig").Linear;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const EFLALayer = struct {
    allocator: std.mem.Allocator,
    hidden_dim: u32,
    num_heads: u32,
    head_dim: u32,
    chunk_size: u32,
    beta_learnable: bool,

    w_q: Linear,
    w_k: Linear,
    w_v: Linear,
    w_out: Linear,
    beta: Tensor,
    beta_grad: Tensor,

    states: []Tensor,

    saved_k: ?Tensor,
    saved_v: ?Tensor,
    saved_beta: ?Tensor,
    saved_lambda: ?Tensor,
    saved_c: ?Tensor,
    saved_states_before: []?Tensor,

    pub fn init(
        allocator: std.mem.Allocator,
        hidden_dim: u32,
        num_heads: u32,
        beta_init: f32,
        beta_learnable: bool,
        chunk_size: u32,
    ) !EFLALayer {
        const head_dim = hidden_dim / num_heads;

        var w_q = try Linear.init(allocator, hidden_dim, hidden_dim, false);
        var w_k = try Linear.init(allocator, hidden_dim, hidden_dim, false);
        var w_v = try Linear.init(allocator, hidden_dim, hidden_dim, false);
        var w_out = try Linear.init(allocator, hidden_dim, hidden_dim, false);

        var beta = try Tensor.init(allocator, &[_]u32{num_heads}, .f32);
        try fillScalar(&beta, beta_init, num_heads, allocator);
        var beta_grad = try Tensor.zeros(allocator, &[_]u32{num_heads}, .f32);

        var states = try allocator.alloc(Tensor, num_heads);
        for (states) |*s| {
            s.* = try Tensor.zeros(allocator, &[_]u32{ head_dim, head_dim }, .f32);
        }

        var saved_states_before = try allocator.alloc(?Tensor, num_heads);
        @memset(saved_states_before, null);

        return EFLALayer{
            .allocator = allocator,
            .hidden_dim = hidden_dim,
            .num_heads = num_heads,
            .head_dim = head_dim,
            .chunk_size = chunk_size,
            .beta_learnable = beta_learnable,
            .w_q = w_q,
            .w_k = w_k,
            .w_v = w_v,
            .w_out = w_out,
            .beta = beta,
            .beta_grad = beta_grad,
            .states = states,
            .saved_k = null,
            .saved_v = null,
            .saved_beta = null,
            .saved_lambda = null,
            .saved_c = null,
            .saved_states_before = saved_states_before,
        };
    }

    pub fn deinit(self: *EFLALayer) void {
        self.w_q.deinit();
        self.w_k.deinit();
        self.w_v.deinit();
        self.w_out.deinit();
        self.beta.deinit();
        self.beta_grad.deinit();
        for (self.states) |*s| s.deinit();
        self.allocator.free(self.states);
        if (self.saved_k) |*t| t.deinit();
        if (self.saved_v) |*t| t.deinit();
        if (self.saved_beta) |*t| t.deinit();
        if (self.saved_lambda) |*t| t.deinit();
        if (self.saved_c) |*t| t.deinit();
        for (self.saved_states_before) |*opt| {
            if (opt.*) |*t| t.deinit();
        }
        self.allocator.free(self.saved_states_before);
    }

    fn fillScalar(t: *Tensor, val: f32, n: u32, allocator: std.mem.Allocator) !void {
        var buf = try allocator.alloc(f32, n);
        defer allocator.free(buf);
        for (buf) |*v| v.* = val;
        try t.copyToDevice(std.mem.sliceAsBytes(buf));
    }

    pub fn forward(self: *EFLALayer, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        var k = try self.w_k.forward(x, allocator);
        var v = try self.w_v.forward(x, allocator);

        if (self.saved_k) |*t| t.deinit();
        if (self.saved_v) |*t| t.deinit();

        const c_mod = @cImport(@cInclude("cuda_runtime.h"));
        var sk = try Tensor.init(allocator, k.shape(), k.dtype);
        _ = c_mod.cudaMemcpy(sk.data_gpu, k.data_gpu, k.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_k = sk;

        var sv = try Tensor.init(allocator, v.shape(), v.dtype);
        _ = c_mod.cudaMemcpy(sv.data_gpu, v.data_gpu, v.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_v = sv;

        defer k.deinit();
        defer v.deinit();

        const shape = x.shape();
        const batch = shape[0];
        const seq_len = shape[1];

        for (self.saved_states_before, 0..) |*opt, hi| {
            if (opt.*) |*t| t.deinit();
            var scopy = try Tensor.init(allocator, self.states[hi].shape(), self.states[hi].dtype);
