            w_beta[i] = try Linear.init(allocator, hidden_dim, hidden_dim, false);
            w_k[i] = try Linear.init(allocator, hidden_dim, hidden_dim, false);
            w_p[i] = try Linear.init(allocator, hidden_dim, hidden_dim, false);
