        var alpha_buf = [_]f32{alpha};
        try alpha_param.copyToDevice(std.mem.asBytes(&alpha_buf));
        var alpha_grad = try Tensor.zeros(allocator, &[_]u32{1}, .f32);

        var state = try Tensor.zeros(allocator, &[_]u32{ hidden_dim, hidden_dim }, .f32);

        var saved_residuals = try allocator.alloc(?Tensor, num_iters + 1);
        @memset(saved_residuals, null);
        var saved_deltas = try allocator.alloc(?Tensor, num_iters);
        @memset(saved_deltas, null);
        var saved_betas = try allocator.alloc(?Tensor, num_iters);
        @memset(saved_betas, null);
        var saved_ks = try allocator.alloc(?Tensor, num_iters);
        @memset(saved_ks, null);
        var saved_ps = try allocator.alloc(?Tensor, num_iters);
        @memset(saved_ps, null);

        return PRISMLayer{
            .allocator = allocator,
            .hidden_dim = hidden_dim,
            .num_iters = num_iters,
            .shortconv_window = shortconv_window,
            .alpha = alpha,
