const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;
const RMSNorm = @import("../nn/rms_norm.zig").RMSNorm;
const Linear = @import("../nn/linear.zig").Linear;
const GELU = @import("../nn/gelu.zig").GELU;
const EFLALayer = @import("efla.zig").EFLALayer;
const PRISMLayer = @import("prism.zig").PRISMLayer;
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const TransformerBlock = struct {
    allocator: std.mem.Allocator,
    hidden_dim: u32,
    ffn_dim: u32,

    norm1: RMSNorm,
    norm2: RMSNorm,
    norm3: RMSNorm,

    efla: EFLALayer,
    prism: PRISMLayer,

    ffn_up: Linear,
    ffn_down: Linear,
    ffn_gelu: GELU,

    w_v_proj: Linear,

    saved_x_pre_efla: ?Tensor,
    saved_x_pre_prism: ?Tensor,
    saved_x_pre_ffn: ?Tensor,
    saved_efla_out: ?Tensor,
    saved_prism_out: ?Tensor,
    saved_ffn_mid: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, cfg: config_mod.ModelConfig) !TransformerBlock {
        var norm1 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps);
        var norm2 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps);
        var norm3 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps);

        var efla = try EFLALayer.init(
            allocator,
            cfg.hidden_dim,
            cfg.num_heads,
            cfg.efla_beta_init,
            cfg.efla_beta_learnable,
            cfg.efla_chunk_size,
        );

        var prism = try PRISMLayer.init(
            allocator,
            cfg.hidden_dim,
            cfg.prism_num_iters,
            cfg.prism_shortconv_window,
            cfg.prism_alpha,
        );

        var ffn_up = try Linear.init(allocator, cfg.hidden_dim, cfg.ffn_dim, false);
        var ffn_down = try Linear.init(allocator, cfg.ffn_dim, cfg.hidden_dim, false);
        var ffn_gelu = GELU.init(allocator);

        var w_v_proj = try Linear.init(allocator, cfg.hidden_dim, cfg.hidden_dim, false);

        return TransformerBlock{
            .allocator = allocator,
            .hidden_dim = cfg.hidden_dim,
            .ffn_dim = cfg.ffn_dim,
            .norm1 = norm1,
            .norm2 = norm2,
            .norm3 = norm3,
            .efla = efla,
            .prism = prism,
            .ffn_up = ffn_up,
            .ffn_down = ffn_down,
            .ffn_gelu = ffn_gelu,
            .w_v_proj = w_v_proj,
            .saved_x_pre_efla = null,
            .saved_x_pre_prism = null,
            .saved_x_pre_ffn = null,
            .saved_efla_out = null,
            .saved_prism_out = null,
            .saved_ffn_mid = null,
        };
    }

    pub fn deinit(self: *TransformerBlock) void {
        self.norm1.deinit();
        self.norm2.deinit();
        self.norm3.deinit();
        self.efla.deinit();
        self.prism.deinit();
        self.ffn_up.deinit();
        self.ffn_down.deinit();
        self.ffn_gelu.deinit();
        self.w_v_proj.deinit();
        if (self.saved_x_pre_efla) |*t| t.deinit();
        if (self.saved_x_pre_prism) |*t| t.deinit();
        if (self.saved_x_pre_ffn) |*t| t.deinit();
        if (self.saved_efla_out) |*t| t.deinit();
        if (self.saved_prism_out) |*t| t.deinit();
        if (self.saved_ffn_mid) |*t| t.deinit();
    }

    pub fn forward(self: *TransformerBlock, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const c_mod = @cImport(@cInclude("cuda_runtime.h"));

        if (self.saved_x_pre_efla) |*t| t.deinit();
        var sx_efla = try Tensor.init(allocator, x.shape(), x.dtype);
        _ = c_mod.cudaMemcpy(sx_efla.data_gpu, x.data_gpu, x.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_x_pre_efla = sx_efla;

        var normed1 = try self.norm1.forward(x, allocator);
        var efla_out = try self.efla.forward(&normed1, allocator);
        normed1.deinit();

        if (self.saved_efla_out) |*t| t.deinit();
        var sef = try Tensor.init(allocator, efla_out.shape(), efla_out.dtype);
        _ = c_mod.cudaMemcpy(sef.data_gpu, efla_out.data_gpu, efla_out.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_efla_out = sef;

        var x_after_efla = try Tensor.zeros(allocator, x.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(x.data_gpu),
            @ptrCast(efla_out.data_gpu),
            @ptrCast(x_after_efla.data_gpu),
            @intCast(x.numElements()),
            null,
        );
        efla_out.deinit();

        if (self.saved_x_pre_prism) |*t| t.deinit();
        var sx_prism = try Tensor.init(allocator, x_after_efla.shape(), x_after_efla.dtype);
        _ = c_mod.cudaMemcpy(sx_prism.data_gpu, x_after_efla.data_gpu, x_after_efla.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_x_pre_prism = sx_prism;

        var normed2 = try self.norm2.forward(&x_after_efla, allocator);
        var v_proj = try self.w_v_proj.forward(&normed2, allocator);
        var prism_out = try self.prism.forward(&normed2, &v_proj, allocator);
        normed2.deinit();
        v_proj.deinit();

        if (self.saved_prism_out) |*t| t.deinit();
        var sp = try Tensor.init(allocator, prism_out.shape(), prism_out.dtype);
        _ = c_mod.cudaMemcpy(sp.data_gpu, prism_out.data_gpu, prism_out.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_prism_out = sp;

        var x_after_prism = try Tensor.zeros(allocator, x_after_efla.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(x_after_efla.data_gpu),
            @ptrCast(prism_out.data_gpu),
            @ptrCast(x_after_prism.data_gpu),
            @intCast(x_after_efla.numElements()),
            null,
        );
        x_after_efla.deinit();
        prism_out.deinit();

        if (self.saved_x_pre_ffn) |*t| t.deinit();
        var sx_ffn = try Tensor.init(allocator, x_after_prism.shape(), x_after_prism.dtype);
        _ = c_mod.cudaMemcpy(sx_ffn.data_gpu, x_after_prism.data_gpu, x_after_prism.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_x_pre_ffn = sx_ffn;

        var normed3 = try self.norm3.forward(&x_after_prism, allocator);
        var ffn_up_out = try self.ffn_up.forward(&normed3, allocator);
        normed3.deinit();

        var ffn_act = try self.ffn_gelu.forward(&ffn_up_out, allocator);

        if (self.saved_ffn_mid) |*t| t.deinit();
        var sfm = try Tensor.init(allocator, ffn_act.shape(), ffn_act.dtype);
        _ = c_mod.cudaMemcpy(sfm.data_gpu, ffn_act.data_gpu, ffn_act.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        self.saved_ffn_mid = sfm;

        ffn_up_out.deinit();

        var ffn_out = try self.ffn_down.forward(&ffn_act, allocator);
        ffn_act.deinit();

        var output = try Tensor.zeros(allocator, x_after_prism.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(x_after_prism.data_gpu),
            @ptrCast(ffn_out.data_gpu),
            @ptrCast(output.data_gpu),
            @intCast(x_after_prism.numElements()),
            null,
        );
        x_after_prism.deinit();
        ffn_out.deinit();

        return output;
    }

    pub fn backward(self: *TransformerBlock, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const x_pre_ffn = self.saved_x_pre_ffn orelse return error.ForwardNotCalled;
        const x_pre_prism = self.saved_x_pre_prism orelse return error.ForwardNotCalled;
        const x_pre_efla = self.saved_x_pre_efla orelse return error.ForwardNotCalled;

        var grad_ffn_out = try Tensor.init(allocator, grad_out.shape(), .f32);
        const c_mod = @cImport(@cInclude("cuda_runtime.h"));
        _ = c_mod.cudaMemcpy(grad_ffn_out.data_gpu, grad_out.data_gpu, grad_out.num_bytes, c_mod.cudaMemcpyDeviceToDevice);
        defer grad_ffn_out.deinit();

        var grad_ffn_act = try self.ffn_down.backward(&grad_ffn_out, allocator);
        var grad_ffn_up_out = try self.ffn_gelu.backward(&grad_ffn_act, allocator);
        grad_ffn_act.deinit();
        var grad_normed3 = try self.ffn_up.backward(&grad_ffn_up_out, allocator);
        grad_ffn_up_out.deinit();
        var grad_before_ffn_norm = try self.norm3.backward(&x_pre_ffn, &grad_normed3, allocator);
        grad_normed3.deinit();

        var grad_after_prism = try Tensor.zeros(allocator, grad_out.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_before_ffn_norm.data_gpu),
            @ptrCast(grad_after_prism.data_gpu),
            @intCast(grad_out.numElements()),
            null,
        );
        grad_before_ffn_norm.deinit();

        var normed2_recompute = try self.norm2.forward(&x_pre_prism, allocator);
        var grad_prism_out = try self.prism.backward(&normed2_recompute, &grad_after_prism, allocator);
        var grad_normed2 = try self.norm2.backward(&x_pre_prism, &grad_prism_out, allocator);
        normed2_recompute.deinit();
        grad_prism_out.deinit();

        var grad_after_efla = try Tensor.zeros(allocator, grad_after_prism.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_after_prism.data_gpu),
            @ptrCast(grad_normed2.data_gpu),
            @ptrCast(grad_after_efla.data_gpu),
            @intCast(grad_after_prism.numElements()),
            null,
        );
        grad_after_prism.deinit();
        grad_normed2.deinit();

        var normed1_recompute = try self.norm1.forward(&x_pre_efla, allocator);
        var grad_efla_out = try self.efla.backward(&normed1_recompute, &grad_after_efla, allocator);
        var grad_normed1 = try self.norm1.backward(&x_pre_efla, &grad_efla_out, allocator);
        normed1_recompute.deinit();
        grad_efla_out.deinit();

        var grad_x = try Tensor.zeros(allocator, grad_after_efla.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_after_efla.data_gpu),
            @ptrCast(grad_normed1.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @intCast(grad_after_efla.numElements()),
            null,
        );
        grad_after_efla.deinit();
        grad_normed1.deinit();

        return grad_x;
    }

    pub fn resetStates(self: *TransformerBlock) !void {
        try self.efla.resetState();
        try self.prism.resetState();
    }
};
