const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;
const Embedding = @import("../nn/embedding.zig").Embedding;
const RMSNorm = @import("../nn/rms_norm.zig").RMSNorm;
const Linear = @import("../nn/linear.zig").Linear;
const TransformerBlock = @import("block.zig").TransformerBlock;
const config_mod = @import("../util/config.zig");
const distributed = @import("../runtime/distributed.zig");
const lion_mod = @import("../optim/lion.zig");
const muon_mod = @import("../optim/muon.zig");
const state_shard_mod = @import("../optim/state_shard.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const ForwardResult = struct {
    loss: f32,
    tokens_processed: u64,
    grad_norm: f32,
};

pub const LanguageModel = struct {
    allocator: std.mem.Allocator,
    cfg: config_mod.ModelConfig,
    dist: *distributed.DistributedRuntime,

    embed: Embedding,
    blocks: []TransformerBlock,
    final_norm: RMSNorm,
    lm_head: ?Linear,

    checkpointed_blocks: []usize,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config_mod.ModelConfig,
        dist: *distributed.DistributedRuntime,
    ) !LanguageModel {
        var embed = try Embedding.init(allocator, cfg.vocab_size, cfg.hidden_dim);

        var blocks = try allocator.alloc(TransformerBlock, cfg.num_layers);
        for (blocks) |*blk| {
            blk.* = try TransformerBlock.init(allocator, cfg);
        }

        var final_norm = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps);

        var lm_head: ?Linear = null;
        if (!cfg.tie_embeddings) {
            lm_head = try Linear.init(allocator, cfg.hidden_dim, cfg.vocab_size, false);
        }

        var checkpointed = try allocator.alloc(usize, cfg.num_layers / cfg.activation_checkpoint_interval + 1);
        var ci: usize = 0;
        var li: usize = 0;
        while (li < cfg.num_layers) : (li += cfg.activation_checkpoint_interval) {
            checkpointed[ci] = li;
            ci += 1;
        }
        const final_checkpointed = try allocator.realloc(checkpointed, ci);

        return LanguageModel{
            .allocator = allocator,
            .cfg = cfg,
            .dist = dist,
            .embed = embed,
            .blocks = blocks,
            .final_norm = final_norm,
            .lm_head = lm_head,
            .checkpointed_blocks = final_checkpointed,
        };
    }

    pub fn deinit(self: *LanguageModel) void {
        self.embed.deinit();
        for (self.blocks) |*blk| blk.deinit();
        self.allocator.free(self.blocks);
        self.final_norm.deinit();
        if (self.lm_head) |*lh| lh.deinit();
        self.allocator.free(self.checkpointed_blocks);
    }

    pub fn forward(self: *LanguageModel, token_ids: []const u32, seq_len: u32, allocator: std.mem.Allocator) !Tensor {
        var x = try self.embed.forward(token_ids, seq_len, allocator);

        for (self.blocks) |*blk| {
            var new_x = try blk.forward(&x, allocator);
            x.deinit();
            x = new_x;
        }

        var normed = try self.final_norm.forward(&x, allocator);
        x.deinit();

        var logits: Tensor = undefined;
        if (self.lm_head) |*lh| {
            logits = try lh.forward(&normed, allocator);
            normed.deinit();
        } else {
            const batch = normed.shape()[0];
            const seq = if (normed.shape().len >= 3) normed.shape()[1] else 1;
            const hidden = self.cfg.hidden_dim;
            const vocab = self.cfg.vocab_size;
            logits = try Tensor.zeros(allocator, &[_]u32{ batch, seq, vocab }, .f32);
            c.launch_tied_lm_head(
                @ptrCast(normed.data_gpu),
                @ptrCast(self.embed.weight.data_gpu),
                @ptrCast(logits.data_gpu),
                @intCast(batch * seq),
                @intCast(vocab),
                @intCast(hidden),
                null,
            );
            normed.deinit();
        }

        return logits;
    }

    pub fn forwardBackward(
        self: *LanguageModel,
        allocator: std.mem.Allocator,
        token_ids: []const u32,
        targets: []const u32,
        label_smoothing: f32,
    ) !ForwardResult {
        const seq_len: u32 = @intCast(token_ids.len);

        var logits = try self.forward(token_ids, seq_len, allocator);
        defer logits.deinit();

        const batch = logits.shape()[0];
        const seq = logits.shape()[1];
        const vocab = self.cfg.vocab_size;

        var targets_gpu: ?*anyopaque = null;
        const nb = targets.len * @sizeOf(u32);
        _ = c.cudaMalloc(&targets_gpu, nb);
        _ = c.cudaMemcpy(targets_gpu, targets.ptr, nb, c.cudaMemcpyHostToDevice);
        defer _ = c.cudaFree(targets_gpu);

        var loss_gpu = try Tensor.zeros(allocator, &[_]u32{1}, .f32);
        defer loss_gpu.deinit();

        var grad_logits = try Tensor.zeros(allocator, logits.shape(), .f32);

        c.launch_cross_entropy_loss(
            @ptrCast(logits.data_gpu),
            @ptrCast(targets_gpu),
            @ptrCast(grad_logits.data_gpu),
            @ptrCast(loss_gpu.data_gpu),
            @intCast(batch * seq),
            @intCast(vocab),
            label_smoothing,
            null,
        );

        var loss_host = [_]f32{0.0};
        _ = c.cudaMemcpy(&loss_host, loss_gpu.data_gpu, @sizeOf(f32), c.cudaMemcpyDeviceToHost);

        try self.backward(allocator, token_ids, seq_len, &grad_logits);
        grad_logits.deinit();

        const grad_norm = try self.computeGradNorm(allocator);

        return ForwardResult{
            .loss = loss_host[0],
            .tokens_processed = @as(u64, batch) * seq,
            .grad_norm = grad_norm,
        };
    }

    fn backward(
        self: *LanguageModel,
        allocator: std.mem.Allocator,
        token_ids: []const u32,
        seq_len: u32,
        grad_logits: *Tensor,
    ) !void {
        _ = token_ids;
        _ = seq_len;

        var grad = try Tensor.init(allocator, grad_logits.shape(), .f32);
        const c_mod = @cImport(@cInclude("cuda_runtime.h"));
        _ = c_mod.cudaMemcpy(grad.data_gpu, grad_logits.data_gpu, grad_logits.num_bytes, c_mod.cudaMemcpyDeviceToDevice);

        var grad_before_head: Tensor = undefined;
        if (self.lm_head) |*lh| {
            grad_before_head = try lh.backward(&grad, allocator);
        } else {
            const batch = grad.shape()[0];
            const seq = if (grad.shape().len >= 3) grad.shape()[1] else 1;
            const vocab = self.cfg.vocab_size;
            const hidden = self.cfg.hidden_dim;
            grad_before_head = try Tensor.zeros(allocator, &[_]u32{ batch, seq, hidden }, .f32);
            c.launch_tied_lm_head_backward(
                @ptrCast(grad.data_gpu),
                @ptrCast(self.embed.weight.data_gpu),
                @ptrCast(grad_before_head.data_gpu),
                @ptrCast(self.embed.weight_grad.data_gpu),
                @intCast(batch * seq),
                @intCast(vocab),
                @intCast(hidden),
                null,
            );
        }
        grad.deinit();

        var grad_norm_x = try self.final_norm.backward(
            &self.blocks[self.blocks.len - 1].saved_x_pre_ffn.?,
            &grad_before_head,
            allocator,
        );
        grad_before_head.deinit();

        var li: i32 = @intCast(self.blocks.len);
        li -= 1;
        while (li >= 0) : (li -= 1) {
            const block_idx: usize = @intCast(li);
            var new_grad = try self.blocks[block_idx].backward(&grad_norm_x, allocator);
            grad_norm_x.deinit();
            grad_norm_x = new_grad;
        }
        grad_norm_x.deinit();
    }

    fn computeGradNorm(self: *LanguageModel, allocator: std.mem.Allocator) !f32 {
        _ = allocator;
        var total_sq: f32 = 0.0;
        for (self.blocks) |*blk| {
            if (blk.ffn_up.weight_grad.data_gpu != null) {
                var host = try self.allocator.alloc(f32, blk.ffn_up.weight_grad.numElements());
                defer self.allocator.free(host);
                _ = @cImport(@cInclude("cuda_runtime.h")).cudaMemcpy(
                    host.ptr,
                    blk.ffn_up.weight_grad.data_gpu,
                    blk.ffn_up.weight_grad.num_bytes,
                    @cImport(@cInclude("cuda_runtime.h")).cudaMemcpyDeviceToHost,
                );
                for (host) |v| total_sq += v * v;
            }
        }
        return @sqrt(total_sq);
    }

    pub fn clipGradients(self: *LanguageModel, max_norm: f32) !void {
        const grad_norm = try self.computeGradNorm(self.allocator);
        if (grad_norm > max_norm) {
            const scale = max_norm / (grad_norm + 1e-6);
            for (self.blocks) |*blk| {
                try scaleGrad(&blk.ffn_up.weight_grad, scale);
                try scaleGrad(&blk.ffn_down.weight_grad, scale);
            }
        }
    }

    fn scaleGrad(t: *Tensor, scale: f32) !void {
        c.launch_scale_inplace(
            @ptrCast(t.data_gpu),
            @intCast(t.numElements()),
            scale,
            null,
        );
    }

    pub fn optimizerStep(
        self: *LanguageModel,
        allocator: std.mem.Allocator,
        lion: *lion_mod.Lion,
        muon: *muon_mod.Muon,
        shard: *state_shard_mod.OptimizerStateShard,
        dist: *distributed.DistributedRuntime,
    ) !void {
        _ = allocator;
        _ = shard;

        for (self.blocks) |*blk| {
            try muon.step(&blk.ffn_up.weight, &blk.ffn_up.weight_grad);
            try muon.step(&blk.ffn_down.weight, &blk.ffn_down.weight_grad);
            try muon.step(&blk.efla.w_q.weight, &blk.efla.w_q.weight_grad);
            try muon.step(&blk.efla.w_k.weight, &blk.efla.w_k.weight_grad);
            try muon.step(&blk.efla.w_v.weight, &blk.efla.w_v.weight_grad);
            try muon.step(&blk.efla.w_out.weight, &blk.efla.w_out.weight_grad);
            for (blk.prism.w_beta) |*w| try muon.step(&w.weight, &w.weight_grad);
            for (blk.prism.w_k) |*w| try muon.step(&w.weight, &w.weight_grad);
            for (blk.prism.w_p) |*w| try muon.step(&w.weight, &w.weight_grad);

            try lion.step(&blk.norm1.weight, &blk.norm1.weight_grad);
            try lion.step(&blk.norm2.weight, &blk.norm2.weight_grad);
            try lion.step(&blk.norm3.weight, &blk.norm3.weight_grad);
            if (blk.efla.beta_learnable) {
                try lion.step(&blk.efla.beta, &blk.efla.beta_grad);
            }
            try lion.step(&blk.prism.conv_weight, &blk.prism.conv_weight_grad);
        }

        try lion.step(&self.final_norm.weight, &self.final_norm.weight_grad);

        try dist.allReduceGrad(&self.embed.weight);
    }
};
