const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Lion = struct {
    allocator: std.mem.Allocator,
    lr: f32,
    beta1: f32,
    beta2: f32,
    weight_decay: f32,
    momentum_map: std.AutoHashMap(usize, Tensor),
    step_count: u64,

    pub fn init(allocator: std.mem.Allocator, lr: f32, beta1: f32, beta2: f32, weight_decay: f32) !Lion {
        return Lion{
            .allocator = allocator,
            .lr = lr,
            .beta1 = beta1,
            .beta2 = beta2,
            .weight_decay = weight_decay,
            .momentum_map = std.AutoHashMap(usize, Tensor).init(allocator),
            .step_count = 0,
        };
    }

    pub fn deinit(self: *Lion) void {
        var it = self.momentum_map.valueIterator();
        while (it.next()) |v| v.deinit();
        self.momentum_map.deinit();
    }

    pub fn setLR(self: *Lion, lr: f32) void {
        self.lr = lr;
    }

    pub fn step(self: *Lion, param: *Tensor, grad: *Tensor) !void {
        const key = @intFromPtr(param.data_gpu);
        const gop = try self.momentum_map.getOrPut(key);
        if (!gop.found_existing) {
            gop.value_ptr.* = try Tensor.zeros(self.allocator, param.shape(), .f32);
        }
        const m = gop.value_ptr;
        const n = param.numElements();
        c.launch_lion_step(
            @ptrCast(param.data_gpu),
            @ptrCast(grad.data_gpu),
            @ptrCast(m.data_gpu),
            @intCast(n),
            self.lr,
            self.beta1,
            self.beta2,
            self.weight_decay,
            null,
        );
        self.step_count += 1;
    }
};
