const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Muon = struct {
    allocator: std.mem.Allocator,
    lr: f32,
    momentum: f32,
    ns_iters: u32,
    momentum_map: std.AutoHashMap(usize, Tensor),
    step_count: u64,

    pub fn init(allocator: std.mem.Allocator, lr: f32, momentum: f32, ns_iters: u32) !Muon {
        return Muon{
            .allocator = allocator,
            .lr = lr,
            .momentum = momentum,
            .ns_iters = ns_iters,
            .momentum_map = std.AutoHashMap(usize, Tensor).init(allocator),
            .step_count = 0,
        };
    }

    pub fn deinit(self: *Muon) void {
        var it = self.momentum_map.valueIterator();
        while (it.next()) |v| v.deinit();
        self.momentum_map.deinit();
    }

    pub fn setLR(self: *Muon, lr: f32) void {
        self.lr = lr;
    }

    pub fn step(self: *Muon, param: *Tensor, grad: *Tensor) !void {
        const key = @intFromPtr(param.data_gpu);
        const gop = try self.momentum_map.getOrPut(key);
        if (!gop.found_existing) {
            gop.value_ptr.* = try Tensor.zeros(self.allocator, param.shape(), .f32);
        }
        const m = gop.value_ptr;
        const n = param.numElements();

        c.launch_newton_schulz(
            @ptrCast(grad.data_gpu),
            @intCast(n),
            @intCast(self.ns_iters),
            null,
        );

        c.launch_muon_step(
