const std = @import("std");

pub const CosineScheduler = struct {
    warmup_steps: u32,
    decay_steps: u32,
    lr_max: f32,
    lr_min: f32,

    pub fn init(warmup_steps: u32, decay_steps: u32, lr_max: f32, lr_min: f32) CosineScheduler {
        return CosineScheduler{
            .warmup_steps = warmup_steps,
            .decay_steps = decay_steps,
            .lr_max = lr_max,
            .lr_min = lr_min,
        };
    }

    pub fn getLR(self: *const CosineScheduler, step: u32) f32 {
        if (step < self.warmup_steps) {
            return self.lr_max * (@as(f32, @floatFromInt(step)) / @as(f32, @floatFromInt(self.warmup_steps)));
        }
        const decay_step = step - self.warmup_steps;
        if (decay_step >= self.decay_steps) {
            return self.lr_min;
        }
        const progress = @as(f32, @floatFromInt(decay_step)) / @as(f32, @floatFromInt(self.decay_steps));
        const cosine = 0.5 * (1.0 + @cos(std.math.pi * progress));
        return self.lr_min + (self.lr_max - self.lr_min) * cosine;
    }
};

pub const WarmupConstantScheduler = struct {
    warmup_steps: u32,
    lr: f32,

    pub fn init(warmup_steps: u32, lr: f32) WarmupConstantScheduler {
        return WarmupConstantScheduler{ .warmup_steps = warmup_steps, .lr = lr };
    }

    pub fn getLR(self: *const WarmupConstantScheduler, step: u32) f32 {
        if (step < self.warmup_steps) {
            return self.lr * (@as(f32, @floatFromInt(step)) / @as(f32, @floatFromInt(self.warmup_steps)));
        }
        return self.lr;
    }
};
