const std = @import("std");

pub const BPEPair = struct {
    left: u32,
    right: u32,
};

pub const BPEModel = struct {
    allocator: std.mem.Allocator,
    vocab: std.ArrayList([]u8),
    merges: std.ArrayList(BPEPair),
    token_to_id: std.StringHashMap(u32),
    byte_vocab_size: u32,

    pub fn load(allocator: std.mem.Allocator, path: []const u8) !BPEModel {
        const file = try std.fs.openFileAbsolute(path, .{});
        defer file.close();
        const data = try file.readToEndAlloc(allocator, 1 << 28);
        defer allocator.free(data);

        var model = BPEModel{
            .allocator = allocator,
            .vocab = std.ArrayList([]u8).init(allocator),
            .merges = std.ArrayList(BPEPair).init(allocator),
            .token_to_id = std.StringHashMap(u32).init(allocator),
            .byte_vocab_size = 256,
        };

        var lines = std.mem.splitScalar(u8, data, '\n');
        var section: u8 = 0;
        var vocab_idx: u32 = 0;

        while (lines.next()) |line| {
            if (line.len == 0) continue;
            if (std.mem.eql(u8, line, "[vocab]")) {
                section = 1;
                continue;
            }
            if (std.mem.eql(u8, line, "[merges]")) {
                section = 2;
                continue;
            }
            if (section == 1) {
                const owned = try allocator.dupe(u8, line);
                try model.vocab.append(owned);
                try model.token_to_id.put(owned, vocab_idx);
                vocab_idx += 1;
            } else if (section == 2) {
                var parts = std.mem.splitScalar(u8, line, ' ');
                const left_str = parts.next() orelse continue;
                const right_str = parts.next() orelse continue;
                const left_id = try std.fmt.parseInt(u32, left_str, 10);
                const right_id = try std.fmt.parseInt(u32, right_str, 10);
                try model.merges.append(BPEPair{ .left = left_id, .right = right_id });
            }
        }

        return model;
    }

    pub fn deinit(self: *BPEModel) void {
        for (self.vocab.items) |v| self.allocator.free(v);
        self.vocab.deinit();
        self.merges.deinit();
        self.token_to_id.deinit();
    }

    pub fn encode(self: *BPEModel, text: []const u8, allocator: std.mem.Allocator) ![]u32 {
        var ids = std.ArrayList(u32).init(allocator);
        for (text) |byte| {
            try ids.append(@as(u32, byte));
        }

        var merge_rank = std.AutoHashMap(u64, u32).init(allocator);
        defer merge_rank.deinit();
        for (self.merges.items, 0..) |mp, rank| {
            const key = (@as(u64, mp.left) << 32) | mp.right;
            try merge_rank.put(key, @intCast(rank));
        }

        while (ids.items.len >= 2) {
            var best_rank: u32 = std.math.maxInt(u32);
            var best_pos: usize = 0;
            var found = false;

            for (0..ids.items.len - 1) |i| {
                const key = (@as(u64, ids.items[i]) << 32) | ids.items[i + 1];
                if (merge_rank.get(key)) |rank| {
                    if (rank < best_rank) {
                        best_rank = rank;
                        best_pos = i;
                        found = true;
                    }
                }
            }

            if (!found) break;

            const merged_id = self.byte_vocab_size + best_rank;
            ids.items[best_pos] = merged_id;
            _ = ids.orderedRemove(best_pos + 1);
        }

        return ids.toOwnedSlice();
    }

    pub fn decode(self: *BPEModel, ids: []const u32, allocator: std.mem.Allocator) ![]u8 {
        var out = std.ArrayList(u8).init(allocator);
        for (ids) |id| {
            if (id < 256) {
                try out.append(@intCast(id));
            } else {
                const vocab_idx = id - self.byte_vocab_size;
                if (vocab_idx < self.vocab.items.len) {
                    try out.appendSlice(self.vocab.items[vocab_idx]);
                }
            }
        }
        return out.toOwnedSlice();
    }
};

pub const BPETrainer = struct {
    allocator: std.mem.Allocator,
    vocab_size: u32,
    merges: std.ArrayList(BPEPair),
    vocab: std.ArrayList([]u8),

    pub fn init(allocator: std.mem.Allocator, vocab_size: u32) !BPETrainer {
        var trainer = BPETrainer{
            .allocator = allocator,
            .vocab_size = vocab_size,
            .merges = std.ArrayList(BPEPair).init(allocator),
            .vocab = std.ArrayList([]u8).init(allocator),
        };
        for (0..256) |i| {
            var byte_str = try allocator.alloc(u8, 1);
            byte_str[0] = @intCast(i);
            try trainer.vocab.append(byte_str);
        }
        return trainer;
    }

    pub fn deinit(self: *BPETrainer) void {
        for (self.vocab.items) |v| self.allocator.free(v);
        self.vocab.deinit();
        self.merges.deinit();
    }

    pub fn trainFromFile(self: *BPETrainer, path: []const u8) !void {
        const file = try std.fs.openFileAbsolute(path, .{});
        defer file.close();
        const text = try file.readToEndAlloc(self.allocator, 1 << 30);
        defer self.allocator.free(text);
        try self.train(text);
    }

    pub fn train(self: *BPETrainer, text: []const u8) !void {
        var corpus = std.ArrayList(u32).init(self.allocator);
        defer corpus.deinit();
        for (text) |b| try corpus.append(@as(u32, b));

        var current_vocab_size: u32 = 256;

        while (current_vocab_size < self.vocab_size and corpus.items.len >= 2) {
            var pair_counts = std.AutoHashMap(u64, u64).init(self.allocator);
            defer pair_counts.deinit();

            for (0..corpus.items.len - 1) |i| {
                const key = (@as(u64, corpus.items[i]) << 32) | corpus.items[i + 1];
                const gop = try pair_counts.getOrPut(key);
                if (!gop.found_existing) gop.value_ptr.* = 0;
                gop.value_ptr.* += 1;
            }

            var best_count: u64 = 0;
            var best_key: u64 = 0;
            var pit = pair_counts.iterator();
            while (pit.next()) |entry| {
                if (entry.value_ptr.* > best_count) {
                    best_count = entry.value_ptr.*;
                    best_key = entry.key_ptr.*;
                }
            }

            if (best_count < 2) break;

            const left: u32 = @intCast(best_key >> 32);
            const right: u32 = @intCast(best_key & 0xFFFFFFFF);
            const new_id = current_vocab_size;
            try self.merges.append(BPEPair{ .left = left, .right = right });

            const left_str = if (left < self.vocab.items.len) self.vocab.items[left] else "";
            const right_str = if (right < self.vocab.items.len) self.vocab.items[right] else "";
            const merged = try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ left_str, right_str });
            try self.vocab.append(merged);

            var new_corpus = std.ArrayList(u32).init(self.allocator);
            var i: usize = 0;
            while (i < corpus.items.len) {
                if (i + 1 < corpus.items.len and corpus.items[i] == left and corpus.items[i + 1] == right) {
                    try new_corpus.append(new_id);
                    i += 2;
                } else {
                    try new_corpus.append(corpus.items[i]);
                    i += 1;
                }
            }
            corpus.deinit();
            corpus = new_corpus;

            current_vocab_size += 1;
        }
    }

    pub fn saveModel(self: *BPETrainer, path: []const u8) !void {
        const file = try std.fs.createFileAbsolute(path, .{});
        defer file.close();
        var writer = file.writer();

        try writer.writeAll("[vocab]\n");
        for (self.vocab.items) |v| {
            try writer.print("{s}\n", .{v});
        }
        try writer.writeAll("[merges]\n");
        for (self.merges.items) |m| {
            try writer.print("{} {}\n", .{ m.left, m.right });
        }
    }
};
