const std = @import("std");

pub const TokenDataset = struct {
    allocator: std.mem.Allocator,
    path: []const u8,
    file: std.fs.File,
    file_size: u64,
    num_tokens: u64,
    current_offset: u64,

    pub fn open(allocator: std.mem.Allocator, path: []const u8) !TokenDataset {
        const file = try std.fs.openFileAbsolute(path, .{});
        const file_size = try file.getEndPos();
        const num_tokens = (file_size - 8) / @sizeOf(u32);

        var header = [_]u32{ 0, 0 };
        _ = try file.readAll(std.mem.sliceAsBytes(&header));

        return TokenDataset{
            .allocator = allocator,
            .path = try allocator.dupe(u8, path),
            .file = file,
            .file_size = file_size,
            .num_tokens = num_tokens,
            .current_offset = 8,
        };
    }

    pub fn close(self: *TokenDataset) void {
        self.file.close();
        self.allocator.free(self.path);
    }

    pub fn readTokens(self: *TokenDataset, buf: []u32) !usize {
        const bytes_needed = buf.len * @sizeOf(u32);
        const bytes_available = self.file_size - self.current_offset;

        if (bytes_available == 0) {
            try self.file.seekTo(8);
            self.current_offset = 8;
        }

        const can_read = @min(bytes_needed, self.file_size - self.current_offset);
        const tokens_to_read = can_read / @sizeOf(u32);

        const n = try self.file.readAll(std.mem.sliceAsBytes(buf[0..tokens_to_read]));
        self.current_offset += n;
        return n / @sizeOf(u32);
    }

    pub fn seekToOffset(self: *TokenDataset, token_offset: u64) !void {
        const byte_offset = 8 + token_offset * @sizeOf(u32);
        try self.file.seekTo(byte_offset);
        self.current_offset = byte_offset;
    }

    pub fn numTokens(self: *const TokenDataset) u64 {
        return self.num_tokens;
    }
};
