const dataset_mod = @import("dataset.zig");

pub const Batch = struct {
    tokens: []u32,
    targets: []u32,
    seq_len: u32,

    pub fn deinit(self: *Batch, allocator: std.mem.Allocator) void {
        allocator.free(self.tokens);
        allocator.free(self.targets);
    }
};

pub const SequencePacker = struct {
    allocator: std.mem.Allocator,
    seq_len: u32,
    shuffle_seed: u64,
    rank: u32,
    world_size: u32,
    doc_buffer: std.ArrayList(u32),
    rng: std.rand.DefaultPrng,
    token_pos: u64,

    pub fn init(
        allocator: std.mem.Allocator,
        seq_len: u32,
        shuffle_seed: u64,
        rank: u32,
        world_size: u32,
    ) !SequencePacker {
        return SequencePacker{
            .allocator = allocator,
            .seq_len = seq_len,
            .shuffle_seed = shuffle_seed,
            .rank = rank,
            .world_size = world_size,
            .doc_buffer = std.ArrayList(u32).init(allocator),
            .rng = std.rand.DefaultPrng.init(shuffle_seed ^ (@as(u64, rank) << 32)),
            .token_pos = 0,
        };
    }

    pub fn deinit(self: *SequencePacker) void {
        self.doc_buffer.deinit();
    }

    pub fn nextBatch(self: *SequencePacker, allocator: std.mem.Allocator, dataset: *dataset_mod.TokenDataset) !Batch {
        const needed = self.seq_len + 1;

        while (self.doc_buffer.items.len < needed) {
            var tmp = try allocator.alloc(u32, 65536);
            defer allocator.free(tmp);
            const n = try dataset.readTokens(tmp);
            if (n == 0) {
                try dataset.seekToOffset(self.rank * self.seq_len);
                const n2 = try dataset.readTokens(tmp);
                if (n2 == 0) break;
                try self.doc_buffer.appendSlice(tmp[0..n2]);
            } else {
                try self.doc_buffer.appendSlice(tmp[0..n]);
            }
        }

        const actual_len = @min(self.seq_len, @as(u32, @intCast(self.doc_buffer.items.len)) -| 1);

        var tokens = try allocator.alloc(u32, actual_len);
        var targets = try allocator.alloc(u32, actual_len);

        @memcpy(tokens, self.doc_buffer.items[0..actual_len]);
        @memcpy(targets, self.doc_buffer.items[1 .. actual_len + 1]);

        const remove = actual_len * self.world_size;
        if (remove < self.doc_buffer.items.len) {
            const remaining = self.doc_buffer.items.len - remove;
            @memcpy(self.doc_buffer.items[0..remaining], self.doc_buffer.items[remove..]);
            self.doc_buffer.shrinkRetainingCapacity(remaining);
        } else {
            self.doc_buffer.clearRetainingCapacity();
        }

        self.token_pos += actual_len;

        return Batch{
            .tokens = tokens,
            .targets = targets,
            .seq_len = actual_len,
        };
    }

    pub fn getTokenPos(self: *const SequencePacker) u64 {
        return self.token_pos;
    }

    pub fn setTokenPos(self: *SequencePacker, pos: u64) void {
        self.token_pos = pos;
    }
};
