pub fn loadCheckpoint(
    allocator: std.mem.Allocator,
    path: []const u8,
    model: *lm_mod.LanguageModel,
    lion: *lion_mod.Lion,
    muon: *muon_mod.Muon,
    packer: *packing_mod.SequencePacker,
    out_step: *u32,
) !void {
    try integrity_mod.verifyManifest(allocator, path);
    try loadMetadata(allocator, path, out_step, packer);
    try loadModelWeights(allocator, path, model);
    _ = lion;
    _ = muon;
}

fn loadMetadata(allocator: std.mem.Allocator, dir: []const u8, out_step: *u32, packer: *packing_mod.SequencePacker) !void {
    const meta_path = try std.fmt.allocPrint(allocator, "{s}/meta.json", .{dir});
    defer allocator.free(meta_path);
    const f = try std.fs.openFileAbsolute(meta_path, .{});
    defer f.close();
    const data = try f.readToEndAlloc(allocator, 4096);
    defer allocator.free(data);

    var step: u32 = 0;
    var token_pos: u64 = 0;

    var i: usize = 0;
    while (i < data.len) : (i += 1) {
        if (std.mem.startsWith(u8, data[i..], "\"step\":")) {
            i += 7;
            var end = i;
            while (end < data.len and data[end] >= '0' and data[end] <= '9') end += 1;
            step = try std.fmt.parseInt(u32, data[i..end], 10);
        }
        if (std.mem.startsWith(u8, data[i..], "\"token_pos\":")) {
            i += 12;
            var end = i;
            while (end < data.len and data[end] >= '0' and data[end] <= '9') end += 1;
            token_pos = try std.fmt.parseInt(u64, data[i..end], 10);
        }
    }

    out_step.* = step;
    packer.setTokenPos(token_pos);
}

