const std = @import("std");
const hash_util = @import("../util/hash.zig");
const io_util = @import("../util/io.zig");

pub fn writeManifest(allocator: std.mem.Allocator, dir: []const u8) !void {
    var dir_handle = try std.fs.openDirAbsolute(dir, .{ .iterate = true });
    defer dir_handle.close();

    var entries = std.ArrayList([]u8).init(allocator);
    defer {
        for (entries.items) |e| allocator.free(e);
        entries.deinit();
    }

    var it = dir_handle.iterate();
    while (try it.next()) |entry| {
        if (entry.kind != .file) continue;
        if (std.mem.eql(u8, entry.name, "manifest.sha256")) continue;
        try entries.append(try allocator.dupe(u8, entry.name));
    }

    std.mem.sort([]u8, entries.items, {}, struct {
        fn lessThan(_: void, a: []u8, b: []u8) bool {
            return std.mem.lessThan(u8, a, b);
        }
    }.lessThan);

    var manifest_buf = std.ArrayList(u8).init(allocator);
    defer manifest_buf.deinit();

    for (entries.items) |name| {
        const fpath = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir, name });
        defer allocator.free(fpath);
        var hash_bytes: [32]u8 = undefined;
        try hash_util.sha256File(fpath, &hash_bytes);
        const hex = try hash_util.hexEncode(&hash_bytes, allocator);
        defer allocator.free(hex);
        try manifest_buf.writer().print("{s}  {s}\n", .{ hex, name });
    }

    const manifest_path = try std.fmt.allocPrint(allocator, "{s}/manifest.sha256", .{dir});
    defer allocator.free(manifest_path);
    const f = try std.fs.createFileAbsolute(manifest_path, .{});
    defer f.close();
    try f.writeAll(manifest_buf.items);
}

pub fn verifyManifest(allocator: std.mem.Allocator, dir: []const u8) !void {
    const manifest_path = try std.fmt.allocPrint(allocator, "{s}/manifest.sha256", .{dir});
    defer allocator.free(manifest_path);

    const f = try std.fs.openFileAbsolute(manifest_path, .{}) catch return;
    defer f.close();
    const data = try f.readToEndAlloc(allocator, 1 << 20);
    defer allocator.free(data);

    var lines = std.mem.splitScalar(u8, data, '\n');
    while (lines.next()) |line| {
        if (line.len < 66) continue;
        const expected_hex = line[0..64];
        const filename = std.mem.trim(u8, line[66..], " \t\r");
        if (filename.len == 0) continue;
        if (std.mem.eql(u8, filename, "manifest.sha256")) continue;

        const fpath = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir, filename });
        defer allocator.free(fpath);

        var actual_hash: [32]u8 = undefined;
        try hash_util.sha256File(fpath, &actual_hash);
        const actual_hex = try hash_util.hexEncode(&actual_hash, allocator);
        defer allocator.free(actual_hex);

        if (!std.mem.eql(u8, expected_hex, actual_hex)) {
            std.debug.print("Checksum mismatch: {s}\n", .{filename});
            return error.CheckpointCorrupted;
        }
    }
}
