const std = @import("std");
const lm_mod = @import("../model/lm.zig");
const dataset_mod = @import("../data/dataset.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub fn evaluate(
    allocator: std.mem.Allocator,
    model: *lm_mod.LanguageModel,
    data_path: []const u8,
    num_tokens: u32,
) !f32 {
    var dataset = try dataset_mod.TokenDataset.open(allocator, data_path);
    defer dataset.close();

    const seq_len: u32 = @min(num_tokens, model.cfg.max_seq_len);
    var token_buf = try allocator.alloc(u32, seq_len + 1);
    defer allocator.free(token_buf);

    const n_read = try dataset.readTokens(token_buf);
    if (n_read < 2) return 0.0;

    const actual_len = @as(u32, @intCast(n_read)) - 1;
    const tokens = token_buf[0..actual_len];
    const targets = token_buf[1 .. actual_len + 1];

    var logits = try model.forward(tokens, actual_len, allocator);
    defer logits.deinit();

    const batch = logits.shape()[0];
    const seq = logits.shape()[1];
    const vocab = model.cfg.vocab_size;

    var targets_gpu: ?*anyopaque = null;
    const nb = targets.len * @sizeOf(u32);
    _ = c.cudaMalloc(&targets_gpu, nb);
    _ = c.cudaMemcpy(targets_gpu, targets.ptr, nb, c.cudaMemcpyHostToDevice);
    defer _ = c.cudaFree(targets_gpu);

    var loss_gpu = try allocator.alloc(f32, 1);
    defer allocator.free(loss_gpu);
    var loss_gpu_ptr: ?*anyopaque = null;
    _ = c.cudaMalloc(&loss_gpu_ptr, @sizeOf(f32));
    defer _ = c.cudaFree(loss_gpu_ptr);

    var dummy_grad = try std.mem.Allocator.alloc(allocator, u8, 0);
    defer allocator.free(dummy_grad);

    var grad_logits_dummy = try @import("../tensor/tensor.zig").Tensor.zeros(
        allocator,
        logits.shape(),
        .f32,
    );
    defer grad_logits_dummy.deinit();

    var loss_tensor = try @import("../tensor/tensor.zig").Tensor.zeros(allocator, &[_]u32{1}, .f32);
    defer loss_tensor.deinit();

    c.launch_cross_entropy_loss(
        @ptrCast(logits.data_gpu),
        @ptrCast(targets_gpu),
        @ptrCast(grad_logits_dummy.data_gpu),
        @ptrCast(loss_tensor.data_gpu),
        @intCast(batch * seq),
        @intCast(vocab),
        0.0,
        null,
    );

    var loss_host: f32 = 0.0;
    _ = c.cudaMemcpy(&loss_host, loss_tensor.data_gpu, @sizeOf(f32), c.cudaMemcpyDeviceToHost);

    const perplexity = @exp(loss_host);
    return perplexity;
}
