const std = @import("std");
const lm_mod = @import("../model/lm.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const GenerationConfig = struct {
    max_new_tokens: u32,
    temperature: f32,
    top_k: u32,
    top_p: f32,
    repetition_penalty: f32,
    eos_id: u32,
};

pub fn generate(
    allocator: std.mem.Allocator,
    model: *lm_mod.LanguageModel,
    prompt_ids: []const u32,
    cfg: GenerationConfig,
) ![]u32 {
    var context = std.ArrayList(u32).init(allocator);
    defer context.deinit();
    try context.appendSlice(prompt_ids);

    var generated = std.ArrayList(u32).init(allocator);

    for (0..cfg.max_new_tokens) |_| {
        const seq_len: u32 = @intCast(context.items.len);
        var logits = try model.forward(context.items, seq_len, allocator);
        defer logits.deinit();

        const vocab = model.cfg.vocab_size;
        var last_logits_host = try allocator.alloc(f32, vocab);
        defer allocator.free(last_logits_host);

        const offset = (seq_len - 1) * vocab * @sizeOf(f32);
        _ = c.cudaMemcpy(
            last_logits_host.ptr,
            @as(*u8, @ptrCast(logits.data_gpu.?)) + offset,
            vocab * @sizeOf(f32),
            c.cudaMemcpyDeviceToHost,
        );

        if (cfg.temperature != 1.0 and cfg.temperature > 0.0) {
            for (last_logits_host) |*v| v.* /= cfg.temperature;
        }

        applyRepetitionPenalty(last_logits_host, context.items, cfg.repetition_penalty);

        const next_token = if (cfg.top_k > 0)
            sampleTopK(last_logits_host, cfg.top_k, allocator)
        else
            argmax(last_logits_host);

        try generated.append(next_token);
        try context.append(next_token);

        if (next_token == cfg.eos_id) break;
    }

    return generated.toOwnedSlice();
}

fn argmax(logits: []const f32) u32 {
    var best_idx: u32 = 0;
    var best_val: f32 = logits[0];
    for (logits, 0..) |v, i| {
        if (v > best_val) {
            best_val = v;
            best_idx = @intCast(i);
        }
    }
    return best_idx;
}

fn sampleTopK(logits: []f32, k: u32, allocator: std.mem.Allocator) u32 {
    _ = allocator;
    const actual_k = @min(k, @as(u32, @intCast(logits.len)));
    var indices = std.ArrayList(u32).init(std.heap.page_allocator);
    defer indices.deinit();
    for (0..logits.len) |i| indices.append(@intCast(i)) catch {};

    std.mem.sort(u32, indices.items, logits, struct {
        fn greaterThan(ctx: []f32, a: u32, b: u32) bool {
            return ctx[a] > ctx[b];
        }
    }.greaterThan);

    var max_logit: f32 = logits[indices.items[0]];
    var sum_exp: f32 = 0.0;
    for (indices.items[0..actual_k]) |idx| {
        sum_exp += @exp(logits[idx] - max_logit);
    }

    var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
    const rand = prng.random();
    const r = rand.float(f32) * sum_exp;
    var cumsum: f32 = 0.0;
    for (indices.items[0..actual_k]) |idx| {
        cumsum += @exp(logits[idx] - max_logit);
        if (cumsum >= r) return idx;
    }
    return indices.items[0];
}

fn applyRepetitionPenalty(logits: []f32, context: []const u32, penalty: f32) void {
    if (penalty == 1.0) return;
    for (context) |tok| {
        if (tok < logits.len) {
            if (logits[tok] > 0) {
                logits[tok] /= penalty;
            } else {
                logits[tok] *= penalty;
            }
        }
    }
}
