const std = @import("std");

pub const StepMetrics = struct {
    step: u32,
    loss: f32,
    lr: f32,
    tokens_processed: u64,
    grad_norm: f32,
    wall_time_ms: u64,
    tokens_per_sec: f64,
};

pub const Metrics = struct {
    step: u32,
    loss: f32,
    lr: f32,
    tokens_processed: u64,
    grad_norm: f32,
    total_tokens: u64,
    start_time_ns: i128,
    last_log_time_ns: i128,

    pub fn init() Metrics {
        return Metrics{
            .step = 0,
            .loss = 0.0,
            .lr = 0.0,
            .tokens_processed = 0,
            .grad_norm = 0.0,
            .total_tokens = 0,
            .start_time_ns = std.time.nanoTimestamp(),
            .last_log_time_ns = std.time.nanoTimestamp(),
        };
    }

    pub fn update(self: *Metrics, step: u32, loss: f32, lr: f32, tokens: u64, grad_norm: f32) void {
        self.step = step;
        self.loss = loss;
        self.lr = lr;
        self.tokens_processed = tokens;
        self.grad_norm = grad_norm;
        self.total_tokens += tokens;
    }

    pub fn getStepMetrics(self: *Metrics) StepMetrics {
        const now = std.time.nanoTimestamp();
        const elapsed_ms = @as(u64, @intCast((now - self.last_log_time_ns) / 1_000_000));
        const elapsed_sec = @as(f64, @floatFromInt(elapsed_ms)) / 1000.0;
        const tps = if (elapsed_sec > 0.0)
            @as(f64, @floatFromInt(self.tokens_processed)) / elapsed_sec
        else
            0.0;
        self.last_log_time_ns = now;
        return StepMetrics{
            .step = self.step,
            .loss = self.loss,
            .lr = self.lr,
            .tokens_processed = self.tokens_processed,
            .grad_norm = self.grad_norm,
            .wall_time_ms = elapsed_ms,
            .tokens_per_sec = tps,
        };
    }
};
