    stderr: std.fs.File,

    pub fn init(allocator: std.mem.Allocator, rank: u32) !Logger {
        var log_file: ?std.fs.File = null;
        if (rank == 0) {
            log_file = try std.fs.createFileAbsolute("/tmp/llm_train.log", .{ .truncate = false });
        }
        return Logger{
            .allocator = allocator,
            .rank = rank,
            .file = log_file,
            .stderr = std.io.getStdErr(),
        };
    }

    pub fn deinit(self: *Logger) void {
        if (self.file) |f| f.close();
    }

    pub fn logInfo(self: *Logger, comptime fmt: []const u8, args: anytype) !void {
        if (self.rank != 0) return;
        const msg = try std.fmt.allocPrint(self.allocator, "[INFO] " ++ fmt ++ "\n", args);
        defer self.allocator.free(msg);
        try self.stderr.writeAll(msg);
        if (self.file) |f| try f.writeAll(msg);
    }

    pub fn logError(self: *Logger, comptime fmt: []const u8, args: anytype) !void {
        const msg = try std.fmt.allocPrint(self.allocator, "[ERROR rank={}] " ++ fmt ++ "\n", .{self.rank} ++ args);
        defer self.allocator.free(msg);
        try self.stderr.writeAll(msg);
        if (self.file) |f| try f.writeAll(msg);
    }

    pub fn logStep(self: *Logger, metrics: *metrics_mod.Metrics) !void {
        if (self.rank != 0) return;
        const sm = metrics.getStepMetrics();
        const msg = try std.fmt.allocPrint(
            self.allocator,
            "[STEP] step={} loss={d:.6} lr={d:.8} grad_norm={d:.4} tok/s={d:.1} wall_ms={}\n",
            .{ sm.step, sm.loss, sm.lr, sm.grad_norm, sm.tokens_per_sec, sm.wall_time_ms },
        );
        defer self.allocator.free(msg);
        try self.stderr.writeAll(msg);
        if (self.file) |f| try f.writeAll(msg);
    }
};
