const std = @import("std");

pub const HealthMonitor = struct {
    fp8_amax_history_len: u32,
    loss_spike_threshold: f32,
    consecutive_nan_count: u32,
    loss_scale: f32,
    scale_growth_interval: u32,
    steps_since_last_nan: u32,

    pub fn init(fp8_amax_history_len: u32) HealthMonitor {
        return HealthMonitor{
            .fp8_amax_history_len = fp8_amax_history_len,
            .loss_spike_threshold = 10.0,
            .consecutive_nan_count = 0,
            .loss_scale = 65536.0,
            .scale_growth_interval = 2000,
            .steps_since_last_nan = 0,
        };
    }

    pub fn detectNaN(self: *HealthMonitor, loss: f32) bool {
        if (std.math.isNan(loss) or std.math.isInf(loss)) {
            self.consecutive_nan_count += 1;
            self.steps_since_last_nan = 0;
            return true;
        }
        self.consecutive_nan_count = 0;
        self.steps_since_last_nan += 1;
        return false;
    }

    pub fn adjustScaling(self: *HealthMonitor) void {
        self.loss_scale /= 2.0;
        if (self.loss_scale < 1.0) self.loss_scale = 1.0;
    }

    pub fn maybeGrowScale(self: *HealthMonitor) void {
        if (self.steps_since_last_nan >= self.scale_growth_interval) {
            self.loss_scale = @min(self.loss_scale * 2.0, 65536.0);
            self.steps_since_last_nan = 0;
        }
    }

    pub fn isHealthy(self: *const HealthMonitor) bool {
        return self.consecutive_nan_count < 10;
    }
};
