#include "kernels.h"
#include <cuda_runtime.h>
#include <math.h>

__global__ void rms_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ out,
    float* __restrict__ saved_rms,
    int hidden,
    float eps
) {
    int row = blockIdx.x;
    const float* x_row = x + row * hidden;
    float* out_row = out + row * hidden;

    __shared__ float smem[1024];
    int tid = threadIdx.x;
    float sum = 0.0f;
    for (int i = tid; i < hidden; i += blockDim.x) {
        float v = x_row[i];
        sum += v * v;
    }
    smem[tid] = sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        __syncthreads();
    }
    float rms = rsqrtf(smem[0] / hidden + eps);
    if (tid == 0 && saved_rms != nullptr) saved_rms[row] = rms;
    __syncthreads();
    for (int i = tid; i < hidden; i += blockDim.x) {
        out_row[i] = x_row[i] * rms * weight[i];
    }
}

__global__ void rms_norm_backward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ grad_out,
    const float* __restrict__ weight,
    const float* __restrict__ saved_rms,
    float* __restrict__ grad_x,
    float* __restrict__ grad_weight,
    int hidden,
    float eps
) {
    int row = blockIdx.x;
    const float* x_row = x + row * hidden;
    const float* go_row = grad_out + row * hidden;
    float* gx_row = grad_x + row * hidden;
    float rms = saved_rms[row];

    __shared__ float smem[1024];
    int tid = threadIdx.x;

    float dot = 0.0f;
    for (int i = tid; i < hidden; i += blockDim.x) {
        dot += go_row[i] * weight[i] * x_row[i];
    }
    smem[tid] = dot;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) smem[tid] += smem[tid + s];
        __syncthreads();
    }
    float dot_total = smem[0];

    for (int i = tid; i < hidden; i += blockDim.x) {
        float xi = x_row[i];
        float gi = go_row[i] * weight[i] * rms;
        float dx = gi - xi * (rms * rms * rms) * dot_total / hidden;
        gx_row[i] = dx;
        atomicAdd(&grad_weight[i], go_row[i] * xi * rms);
    }
}

extern "C" void launch_rms_norm(
    const float* x, const float* weight, float* out, float* saved_rms,
    int batch, int seq_len, int hidden, float eps, void* stream
) {
    int total = batch * seq_len;
    int threads = (hidden < 1024) ? hidden : 1024;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    rms_norm_kernel<<<total, threads, threads * sizeof(float), s>>>(x, weight, out, saved_rms, hidden, eps);
}

extern "C" void launch_rms_norm_backward(
    const float* x, const float* grad_out, const float* weight, const float* saved_rms,
    float* grad_x, float* grad_weight, int batch, int seq_len, int hidden, float eps, void* stream
) {
    int total = batch * seq_len;
    int threads = (hidden < 1024) ? hidden : 1024;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    rms_norm_backward_kernel<<<total, threads, threads * sizeof(float), s>>>(x, grad_out, weight, saved_rms, grad_x, grad_weight, hidden, eps);
}
