#include "kernels.h"
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float gelu_fwd(float x) {
    const float sqrt2_inv = 0.7071067811865476f;
    return 0.5f * x * (1.0f + erff(x * sqrt2_inv));
}

__device__ __forceinline__ float gelu_bwd(float x) {
    const float sqrt2_inv = 0.7071067811865476f;
    const float inv_sqrt2pi = 0.3989422804014327f;
    float cdf = 0.5f * (1.0f + erff(x * sqrt2_inv));
    float pdf = inv_sqrt2pi * expf(-0.5f * x * x);
    return cdf + x * pdf;
}

__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = gelu_fwd(x[i]);
}

__global__ void gelu_backward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ grad_out,
    float* __restrict__ grad_x,
    int n
) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) grad_x[i] = grad_out[i] * gelu_bwd(x[i]);
}

extern "C" void launch_gelu(const float* x, float* out, int n, void* stream) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    gelu_kernel<<<blocks, threads, 0, s>>>(x, out, n);
}

extern "C" void launch_gelu_backward(const float* x, const float* grad_out, float* grad_x, int n, void* stream) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    gelu_backward_kernel<<<blocks, threads, 0, s>>>(x, grad_out, grad_x, n);
}
