#include "kernels.h"
#include <cuda_runtime.h>
#include <cublas_v2.h>

static cublasHandle_t g_handle = nullptr;

static cublasHandle_t get_cublas_handle() {
    if (!g_handle) cublasCreate(&g_handle);
    return g_handle;
}

extern "C" void launch_gemm_forward(
    const float* x,
    const float* weight,
    const float* bias,
    float* out,
    int M, int N, int K,
    void* stream
) {
    cublasHandle_t handle = get_cublas_handle();
    if (stream) cublasSetStream(handle, (cudaStream_t)stream);
    float alpha = 1.0f, beta = 0.0f;
    cublasSgemm(handle,
        CUBLAS_OP_T, CUBLAS_OP_N,
        N, M, K,
        &alpha,
        weight, K,
        x, K,
        &beta,
        out, N
    );
    if (bias) {
        int threads = 256;
        int blocks = (M * N + threads - 1) / threads;
        cudaStream_t s = stream ? (cudaStream_t)stream : 0;
        auto add_bias = [=] __device__ (int idx) {
            int col = idx % N;
            out[idx] += bias[col];
        };
        auto kernel = [add_bias] __global__ (int total) {
            int i = blockIdx.x * blockDim.x + threadIdx.x;
            if (i < total) add_bias(i);
        };
        (void)kernel;
    }
}

__global__ void add_bias_kernel(float* out, const float* bias, int M, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < M * N) {
        int col = i % N;
        out[i] += bias[col];
    }
}

extern "C" void launch_gemm_forward_with_bias(
    const float* x, const float* weight, const float* bias, float* out,
    int M, int N, int K, void* stream
) {
    launch_gemm_forward(x, weight, bias, out, M, N, K, stream);
    if (bias) {
        int threads = 256;
        int blocks = (M * N + threads - 1) / threads;
        cudaStream_t s = stream ? (cudaStream_t)stream : 0;
        add_bias_kernel<<<blocks, threads, 0, s>>>(out, bias, M, N);
    }
}

extern "C" void launch_gemm_backward(
    const float* input,
    const float* weight,
    const float* grad_out,
    float* grad_input,
    float* grad_weight,
    float* grad_bias,
    int M, int N, int K,
    void* stream
) {
    cublasHandle_t handle = get_cublas_handle();
    if (stream) cublasSetStream(handle, (cudaStream_t)stream);
    float alpha = 1.0f, beta = 0.0f;

    cublasSgemm(handle,
        CUBLAS_OP_N, CUBLAS_OP_N,
        K, M, N,
        &alpha,
        weight, K,
        grad_out, N,
        &beta,
        grad_input, K
    );

    cublasSgemm(handle,
        CUBLAS_OP_N, CUBLAS_OP_T,
        K, N, M,
        &alpha,
        input, K,
        grad_out, N,
        &beta,
        grad_weight, K
    );

    if (grad_bias) {
        float one = 1.0f;
        float* ones;
        cudaMalloc(&ones, M * sizeof(float));
        cudaMemset(ones, 0, M * sizeof(float));
        cublasSgemv(handle,
            CUBLAS_OP_N,
            N, M,
            &one,
            grad_out, N,
            ones, 1,
            &beta,
            grad_bias, 1
        );
        cudaFree(ones);
    }
}
