```cuda
#include "kernels.h"
#include <cuda_runtime.h>
#include <math.h>

__global__ void efla_forward_kernel(
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ beta,
    float* __restrict__ state,
    float* __restrict__ output,
    float* __restrict__ lambda_out,
    float* __restrict__ c_out,
    int seq_len,
    int num_heads,
    int head_dim,
    int chunk_size
) {
    int head = blockIdx.x;
    int batch = blockIdx.y;
    int tid = threadIdx.x;

    float b = beta[head];

    float* h = state + (batch * num_heads + head) * head_dim * head_dim;

    for (int t = 0; t < seq_len; t++) {
        int idx = (batch * seq_len + t) * num_heads * head_dim + head * head_dim;
        const float* kt = k + idx;
        const float* vt = v + idx;
        float* ot = output + idx;

        __shared__ float kk[256];
        __shared__ float hk[256];

        if (tid < head_dim) {
            kk[tid] = kt[tid];
        }
        __syncthreads();

        float dot_hk = 0.0f;
        if (tid < head_dim) {
            for (int d = 0; d < head_dim; d++) {
                dot_hk += h[tid * head_dim + d] * kk[d];
            }
            hk[tid] = dot_hk;
        }
        __syncthreads();

        float c = 0.0f;
        float lambda_t = 0.0f;
        if (tid == 0) {
            for (int d = 0; d < head_dim; d++) {
                c += kk[d] * hk[d];
            }
            lambda_t = 1.0f / (1.0f + b * c);
            if (lambda_out) lambda_out[(batch * seq_len + t) * num_heads + head] = lambda_t;
            if (c_out) c_out[(batch * seq_len + t) * num_heads + head] = c;
        }
        __syncthreads();

        if (tid < head_dim) {
            float outer_scale = b * lambda_t;
            float delta = vt[tid] - hk[tid];
            for (int d = 0; d < head_dim; d++) {
                atomicAdd(&h[tid * head_dim + d], outer_scale * delta * kk[d]);
            }
            ot[tid] = hk[tid] + lambda_t * delta;
        }
        __syncthreads();
    }
}

__global__ void efla_backward_kernel(
    const float* __restrict__ k,
    const float* __restrict__ v,
    const float* __restrict__ beta,
    const float* __restrict__ c,
    const float* __restrict__ lambda_t,
    const float* __restrict__ grad_out,
    float* __restrict__ grad_k,
    float* __restrict__ grad_v,
    float* __restrict__ grad_beta,
    int seq_len,
    int num_heads,
    int head_dim
) {
    int head = blockIdx.x;
    int batch = blockIdx.y;
    int tid = threadIdx.x;

    float b = beta[head];
    float gb_accum = 0.0f;

    for (int t = seq_len - 1; t >= 0; t--) {
        int bidx = (batch * seq_len + t) * num_heads + head;
        float c_t = c[bidx];
        float lam = lambda_t[bidx];

        int vidx = (batch * seq_len + t) * num_heads * head_dim + head * head_dim;
        const float* kt = k + vidx;
        const float* vt = v + vidx;
        const float* got = grad_out + vidx;
        float* gkt = grad_k + vidx;
        float* gvt = grad_v + vidx;

        if (tid < head_dim) {
            gvt[tid] += got[tid] * lam;
            float dlam = 0.0f;
            for (int d = 0; d < head_dim; d++) dlam += got[d] * (vt[d] - 0.0f);
            float dc = -b * lam * lam * dlam;
            gkt[tid] += dc * kt[tid] * 2.0f;
            gb_accum += -lam * lam * dlam * c_t;
        }
    }

    if (tid == 0) {
        atomicAdd(&grad_beta[head], gb_accum);
    }
}

extern "C" void launch_efla_forward(
    const float* k, const float* v, const float* beta,
    void* states, float* output, float* lambda_out, float* c_out,
    int batch, int seq_len, int num_heads, int head_dim, int chunk_size,
    void* stream
) {
    float* state_ptr = (float*)states;
    dim3 grid(num_heads, batch);
    int threads = (head_dim < 256) ? head_dim : 256;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    efla_forward_kernel<<<grid, threads, 512 * sizeof(float), s>>>(
        k, v, beta, state_ptr, output, lambda_out, c_out,
        seq_len, num_heads, head_dim, chunk_size
    );
}

extern "C" void launch_efla_backward(
    const float* k, const float* v, const float* beta,
    const float* c, const float* lambda_t, const float* grad_out,
    float* grad_k, float* grad_v, float* grad_beta,
    void* states,
    int batch, int seq_len, int num_heads, int head_dim,
    void* stream
) {
    dim3 grid(num_heads, batch);
    int threads = (head_dim < 256) ? head_dim : 256;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    efla_backward_kernel<<<grid, threads, 0, s>>>(
        k, v, beta, c, lambda_t, grad_out,
        grad_k, grad_v, grad_beta,
        seq_len, num_heads, head_dim
    );
}
