#include "kernels.h"
#include <cuda_runtime.h>

__global__ void prism_state_update_kernel(
    float* __restrict__ state,
    const float** __restrict__ betas,
    const float** __restrict__ ks,
    const float** __restrict__ deltas,
    int num_iters,
    int hidden,
    float alpha
) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if (i >= hidden || j >= hidden) return;

    float s = state[i * hidden + j];
    for (int l = 0; l < num_iters; l++) {
        float k_j = ks[l][j];
        float delta_i = deltas[l][i];
        float beta_i = betas[l][i];
        s = alpha * s + beta_i * delta_i * k_j;
    }
    state[i * hidden + j] = s;
}

extern "C" void launch_prism_state_update(
    float* state,
    void* betas,
    void* ks,
    void* deltas,
    int num_iters,
    int hidden,
    float alpha,
    void* stream
) {
    dim3 threads(16, 16);
    dim3 blocks((hidden + 15) / 16, (hidden + 15) / 16);
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    prism_state_update_kernel<<<blocks, threads, 0, s>>>(
        state,
        (const float**)betas,
        (const float**)ks,
        (const float**)deltas,
        num_iters, hidden, alpha
    );
}
