#include "kernels.h"
#include <cuda_runtime.h>

__global__ void short_conv_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ out,
    int batch,
    int seq_len,
    int hidden,
    int window
) {
    int b = blockIdx.z;
    int t = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;
    if (t >= seq_len || h >= hidden) return;

    float val = 0.0f;
    for (int w = 0; w < window; w++) {
        int ts = t - w;
        if (ts >= 0) {
            val += x[(b * seq_len + ts) * hidden + h] * weight[w * hidden + h];
        }
    }
    out[(b * seq_len + t) * hidden + h] = val;
}

__global__ void short_conv_backward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ grad_out,
    const float* __restrict__ weight,
    float* __restrict__ grad_x,
    float* __restrict__ grad_weight,
    int batch,
    int seq_len,
    int hidden,
    int window
) {
    int b = blockIdx.z;
    int t = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;
    if (t >= seq_len || h >= hidden) return;

    float go = grad_out[(b * seq_len + t) * hidden + h];

    for (int w = 0; w < window; w++) {
        int ts = t - w;
        if (ts >= 0) {
            atomicAdd(&grad_x[(b * seq_len + ts) * hidden + h], go * weight[w * hidden + h]);
            atomicAdd(&grad_weight[w * hidden + h], go * x[(b * seq_len + ts) * hidden + h]);
        }
    }
}

extern "C" void launch_short_conv(
    const float* x, const float* weight, float* out,
    int batch, int seq_len, int hidden, int window, void* stream
) {
