#include "kernels.h"
#include <cuda_runtime.h>

__global__ void scan_forward_kernel(
    const float* __restrict__ a,
    const float* __restrict__ b,
    float* __restrict__ out,
    int n
) {
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) sdata[tid] = a[i] + b[i];
    else sdata[tid] = 0.0f;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) sdata[tid] += sdata[tid + s];
        __syncthreads();
    }

    if (tid == 0) out[blockIdx.x] = sdata[0];
}

extern "C" void launch_scan_forward(
    const float* a, const float* b, float* out, int n, void* stream
) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    scan_forward_kernel<<<blocks, threads, threads * sizeof(float), s>>>(a, b, out, n);
}
