#include "kernels.h"
#include <cuda_runtime.h>
#include <cublas_v2.h>

extern cublasHandle_t g_handle;

__global__ void scale_kernel(float* x, int n, float s) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) x[i] *= s;
}

__global__ void elementwise_add_inplace_kernel(float* a, const float* b, int n, float alpha) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) a[i] += alpha * b[i];
}

extern "C" void launch_newton_schulz(float* g, int n, int iters, void* stream) {
    cudaStream_t s = stream ? (cudaStream_t)stream : 0;
    int dim = (int)sqrtf((float)n);
    if (dim * dim != n) {
        return;
    }

    int threads = 256;
    int blocks = (n + threads - 1) / threads;

    float norm;
    cublasHandle_t handle = g_handle;
    if (!handle) cublasCreate(&handle);
    cublasSnrm2(handle, n, g, 1, &norm);
    if (norm > 0.0f) {
        float scale = 1.0f / norm;
        scale_kernel<<<blocks, threads, 0, s>>>(g, n, scale);
    }

    float* tmp;
    cudaMalloc(&tmp, n * sizeof(float));

    for (int iter = 0; iter < iters; iter++) {
        float alpha = 1.5f, beta = -0.5f;
        float one = 1.0f, zero = 0.0f;

        cublasSgemm(handle,
            CUBLAS_OP_N, CUBLAS_OP_N,
            dim, dim, dim,
            &one,
            g, dim,
            g, dim,
            &zero,
            tmp, dim
        );

        scale_kernel<<<blocks, threads, 0, s>>>(tmp, n, beta);
        elementwise_add_inplace_kernel<<<blocks, threads, 0, s>>>(tmp, g, n, alpha);

        cudaMemcpy(g, tmp, n * sizeof(float), cudaMemcpyDeviceToDevice);
    }

    cudaFree(tmp);
}
