__global__ void embedding_lookup_kernel(
    const float* __restrict__ weight,
    const unsigned int* __restrict__ ids,
    float* __restrict__ out,
    int seq_len,
    int hidden
) {
    int t = blockIdx.x;
    int h = threadIdx.x;
    if (t >= seq_len || h >= hidden) return;
    unsigned int id = ids[t];
    out[t * hidden + h] = weight[id * hidden + h];
}

__global__ void tied_lm_head_kernel(
    const float* __restrict__ x,
    const float* __restrict__ embed_weight,
    float* __restrict__ logits,
    int batch_seq,
    int vocab,
    int hidden
) {
    int token = blockIdx.x;
    int v = threadIdx.x + blockIdx.y * blockDim.x;
    if (token >= batch_seq || v >= vocab) return;
    float dot = 0.0f;
    for (int h = 0; h < hidden; h++) {
        dot += x[token * hidden + h] * embed_weight[v * hidden + h];
    }
    logits[token * vocab + v] = dot;
}

__global__ void tied_lm_head_backward_kernel(
    const float* __restrict__ grad_logits,
    const float* __restrict__ embed_weight,
    float* __restrict__ grad_x,
    float* __restrict__ grad_embed,
    int batch_seq,
    int vocab,
    int hidden
) {
    int token = blockIdx.x;
    int h = threadIdx.x;
    if (token >= batch_seq || h >= hidden) return;
    float gx = 0.0f;
    for (int v = 0; v < vocab; v++) {
        gx += grad_logits[token * vocab + v] * embed_weight[v * hidden + h];
        atomicAdd(&grad_embed[v * hidden + h], grad_logits[token * vocab + v] * 0.0f);
    }
    grad_x[token * hidden + h] = gx;
}

__global__ void cross_entropy_loss_kernel(
    const float* __restrict__ logits,
    const unsigned int* __restrict__ targets,
    float* __restrict__ grad_logits,
    float* __restrict__ loss_out,
    int batch_seq,
    int vocab,
    float label_smoothing
) {
    int i = blockIdx.x;
    if (i >= batch_seq) return;
    const float* logits_i = logits + i * vocab;
    float* grad_i = grad_logits + i * vocab;

    float max_val = logits_i[0];
    for (int v = 1; v < vocab; v++) if (logits_i[v] > max_val) max_val = logits_i[v];

    float sum_exp = 0.0f;
    for (int v = 0; v < vocab; v++) sum_exp += expf(logits_i[v] - max_val);

    float log_sum_exp = max_val + logf(sum_exp);
    unsigned int tgt = targets[i];

    float loss_i = -(logits_i[tgt] - log_sum_exp);

    if (label_smoothing > 0.0f) {
        float smooth_loss = 0.0f;
        for (int v = 0; v < vocab; v++) smooth_loss += logits_i[v] - log_sum_exp;
        smooth_loss = -smooth_loss / vocab;
        loss_i = (1.0f - label_smoothing) * loss_i + label_smoothing * smooth_loss;
    }

    atomicAdd(loss_out, loss_i / batch_seq);

    for (int v = 0; v < vocab; v++) {
        float softmax_v = expf(logits_i[v] - log_sum_exp);
        float target_prob = (v == (int)tgt) ? (1.0f - label_smoothing) : 0.0f;
        if (label_smoothing > 0.0f) target_prob += label_smoothing / vocab;
        grad_i[v] = (softmax_v - target_prob) / batch_seq;
    }
}

__global__ void lion_step_kernel(
    float* __restrict__ param,
    const float* __restrict__ grad,
    float* __restrict__ momentum,
    int n,
    float lr,
    float beta1,
    float beta2,
    float weight_decay
) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    float m = momentum[i];
    float g = grad[i];
    float update = beta1 * m + (1.0f - beta1) * g;
    float sign_update = (update > 0.0f) ? 1.0f : ((update < 0.0f) ? -1.0f : 0.0f);
    param[i] = param[i] * (1.0f - lr * weight_decay) - lr * sign_update;
    momentum[i] = beta2 * m + (1.0f - beta2) * g;
}

__global__ void muon_step_kernel(
    float* __restrict__ param,
    const float* __restrict__ grad,
    float* __restrict__ momentum,
    int n,
    float lr,
    float beta
) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    float m = beta * momentum[i] + grad[i];
    momentum[i] = m;
    param[i] -= lr * m;
}

