```python
import argparse
import os
import struct
import hashlib
import json


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def convert_to_safetensors(ckpt_dir, output_path):
    meta_path = os.path.join(ckpt_dir, "meta.json")
    with open(meta_path) as f:
        meta = json.load(f)
    print(f"Converting checkpoint at step {meta.get('step', '?')}")

    tensors = {}
    for root, dirs, files in os.walk(ckpt_dir):
        for fname in sorted(files):
            if not fname.endswith(".bin"):
                continue
            fpath = os.path.join(root, fname)
            rel = os.path.relpath(fpath, ckpt_dir)
            key = rel.replace(os.sep, "/").replace(".bin", "")
            with open(fpath, "rb") as f:
                data = f.read()
            tensors[key] = data
            print(f"  Loaded {key}: {len(data)} bytes")

    header = {}
    data_offset = 0
    tensor_data = []
    for key, data in tensors.items():
        n_floats = len(data) // 4
        header[key] = {
            "dtype": "F32",
            "shape": [n_floats],
            "data_offsets": [data_offset, data_offset + len(data)],
        }
        tensor_data.append(data)
        data_offset += len(data)

    header_bytes = json.dumps(header, separators=(",", ":")).encode("utf-8")
    header_len = len(header_bytes)

    with open(output_path, "wb") as f:
        f.write(struct.pack("<Q", header_len))
        f.write(header_bytes)
        for d in tensor_data:
            f.write(d)

    print(f"Saved safetensors checkpoint to {output_path}")
    checksum = sha256_file(output_path)
    print(f"SHA256: {checksum}")


def main():
    parser = argparse.ArgumentParser(description="Convert llm-train checkpoint to safetensors")
    parser.add_argument("ckpt_dir", help="Path to checkpoint directory")
    parser.add_argument("output", help="Output .safetensors file path")
    args = parser.parse_args()
    convert_to_safetensors(args.ckpt_dir, args.output)


if __name__ == "__main__":
    main()
```

