            .f16 => "float16",
            .bf16 => "bfloat16",
            .f8e4m3 => "float8_e4m3",
            .f8e5m2 => "float8_e5m2",
            .u32 => "uint32",
            .i32 => "int32",
            .i64 => "int64",
