const std = @import("std");
const DType = @import("dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
});

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    dims: [8]u32,
    ndims: u8,
    dtype: DType,
    data_gpu: ?*anyopaque,
    num_bytes: usize,
    grad: ?*Tensor,
    requires_grad: bool,

    pub fn init(allocator: std.mem.Allocator, shape: []const u32, dtype: DType) !Tensor {
        var t = Tensor{
            .allocator = allocator,
            .dims = [_]u32{0} ** 8,
            .ndims = @intCast(shape.len),
            .dtype = dtype,
            .data_gpu = null,
            .num_bytes = 0,
            .grad = null,
            .requires_grad = false,
        };
        var total: usize = 1;
        for (shape, 0..) |d, i| {
            t.dims[i] = d;
            total *= d;
        }
        t.num_bytes = total * dtype.byteSize();
        if (t.num_bytes > 0) {
            const err = c.cudaMalloc(&t.data_gpu, t.num_bytes);
            if (err != c.cudaSuccess) return error.CudaOutOfMemory;
        }
        return t;
    }

    pub fn zeros(allocator: std.mem.Allocator, shape: []const u32, dtype: DType) !Tensor {
        var t = try Tensor.init(allocator, shape, dtype);
        if (t.num_bytes > 0) {
            const err = c.cudaMemset(t.data_gpu, 0, t.num_bytes);
            if (err != c.cudaSuccess) return error.CudaError;
        }
        return t;
    }

    pub fn deinit(self: *Tensor) void {
        if (self.data_gpu) |ptr| {
            _ = c.cudaFree(ptr);
            self.data_gpu = null;
        }
        if (self.grad) |g| {
            g.deinit();
            self.allocator.destroy(g);
            self.grad = null;
        }
    }

    pub fn shape(self: *const Tensor) []const u32 {
        return self.dims[0..self.ndims];
    }

    pub fn ndim(self: *const Tensor) u8 {
        return self.ndims;
    }

    pub fn numElements(self: *const Tensor) usize {
        if (self.ndims == 0) return 0;
        var n: usize = 1;
        for (self.dims[0..self.ndims]) |d| n *= d;
        return n;
    }

    pub fn initGrad(self: *Tensor) !void {
        if (self.grad != null) return;
        const g = try self.allocator.create(Tensor);
        g.* = try Tensor.zeros(self.allocator, self.shape(), self.dtype);
        self.grad = g;
        self.requires_grad = true;
    }

    pub fn zeroGrad(self: *Tensor) !void {
        if (self.grad) |g| {
            if (g.num_bytes > 0) {
                const err = c.cudaMemset(g.data_gpu, 0, g.num_bytes);
                if (err != c.cudaSuccess) return error.CudaError;
            }
        }
    }

    pub fn copyToHost(self: *const Tensor, allocator: std.mem.Allocator) ![]u8 {
        const buf = try allocator.alloc(u8, self.num_bytes);
        if (self.num_bytes > 0 and self.data_gpu != null) {
            const err = c.cudaMemcpy(buf.ptr, self.data_gpu, self.num_bytes, c.cudaMemcpyDeviceToHost);
            if (err != c.cudaSuccess) {
                allocator.free(buf);
                return error.CudaError;
            }
        }
        return buf;
    }

    pub fn copyToDevice(self: *Tensor, data: []const u8) !void {
        if (data.len != self.num_bytes) return error.SizeMismatch;
        if (self.num_bytes > 0 and self.data_gpu != null) {
            const err = c.cudaMemcpy(self.data_gpu, data.ptr, self.num_bytes, c.cudaMemcpyHostToDevice);
            if (err != c.cudaSuccess) return error.CudaError;
        }
    }

    pub fn copyFrom(self: *Tensor, other: *const Tensor) !void {
        if (self.num_bytes != other.num_bytes) return error.SizeMismatch;
        if (self.num_bytes > 0) {
            const err = c.cudaMemcpy(self.data_gpu, other.data_gpu, self.num_bytes, c.cudaMemcpyDeviceToDevice);
            if (err != c.cudaSuccess) return error.CudaError;
        }
    }

    pub fn reshape(self: *Tensor, new_shape: []const u32) !void {
        var new_total: usize = 1;
        for (new_shape) |d| new_total *= d;
        if (new_total * self.dtype.byteSize() != self.num_bytes) return error.ShapeMismatch;
        self.ndims = @intCast(new_shape.len);
        for (new_shape, 0..) |d, i| self.dims[i] = d;
    }
};
