const std = @import("std");

pub fn shardedSize(total: u64, rank: u32, world_size: u32) u32 {
    const base = total / world_size;
    const remainder = total % world_size;
    if (@as(u64, rank) < remainder) {
        return @intCast(base + 1);
    }
    return @intCast(base);
}

pub fn shardedOffset(total: u64, rank: u32, world_size: u32) u64 {
    const base = total / world_size;
    const remainder = total % world_size;
    if (@as(u64, rank) < remainder) {
        return @as(u64, rank) * (base + 1);
    }
    return remainder * (base + 1) + (@as(u64, rank) - remainder) * base;
}

pub fn allGatherSizes(total: u64, world_size: u32, allocator: std.mem.Allocator) ![]u32 {
    var sizes = try allocator.alloc(u32, world_size);
    for (0..world_size) |r| {
        sizes[r] = shardedSize(total, @intCast(r), world_size);
    }
    return sizes;
}
