const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const DType = @import("../tensor/dtype.zig").DType;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Linear = struct {
    allocator: std.mem.Allocator,
    in_features: u32,
    out_features: u32,
    weight: Tensor,
    bias: ?Tensor,
    use_bias: bool,

    pub fn init(
        allocator: std.mem.Allocator,
        in_features: u32,
        out_features: u32,
        use_bias: bool,
    ) !Linear {
        var weight = try Tensor.init(allocator, &[_]u32{ out_features, in_features }, .f32);
        try initKaimingUniform(&weight, in_features);

        var bias_opt: ?Tensor = null;
        if (use_bias) {
            var bias = try Tensor.zeros(allocator, &[_]u32{out_features}, .f32);
            try initUniformBias(&bias, in_features);
            bias_opt = bias;
        }

        try weight.initGrad();
        if (bias_opt) |*b| try b.initGrad();

        return Linear{
            .allocator = allocator,
            .in_features = in_features,
            .out_features = out_features,
            .weight = weight,
            .bias = bias_opt,
            .use_bias = use_bias,
        };
    }

    pub fn deinit(self: *Linear) void {
        self.weight.deinit();
        if (self.bias) |*b| b.deinit();
    }

    pub fn forward(self: *Linear, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const batch_seq = x.numElements() / self.in_features;
        var out = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.out_features }, .f32);

        const bias_ptr: ?*anyopaque = if (self.bias != null) self.bias.?.data_gpu else null;

        c.launch_gemm_forward(
            @ptrCast(x.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(bias_ptr),
            @ptrCast(out.data_gpu),
            @intCast(batch_seq),
            @intCast(self.out_features),
            @intCast(self.in_features),
            null,
        );
        return out;
    }

    pub fn backward(self: *Linear, x: *Tensor, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const batch_seq = x.numElements() / self.in_features;
        var grad_x = try Tensor.zeros(allocator, x.shape(), .f32);

        const bias_grad_ptr: ?*anyopaque = if (self.bias != null) self.bias.?.grad.?.data_gpu else null;

        c.launch_gemm_backward(
            @ptrCast(x.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @ptrCast(self.weight.grad.?.data_gpu),
            @ptrCast(bias_grad_ptr),
            @intCast(batch_seq),
            @intCast(self.out_features),
            @intCast(self.in_features),
            null,
        );
        return grad_x;
    }
};

fn initKaimingUniform(t: *Tensor, fan_in: u32) !void {
    const n = t.numElements();
    var host = try t.allocator.alloc(f32, n);
    defer t.allocator.free(host);

    const bound = @sqrt(3.0 / @as(f32, @floatFromInt(fan_in)));
    var prng = std.rand.DefaultPrng.init(0xDEADBEEF + fan_in);
    const rand = prng.random();
    for (host) |*v| {
        v.* = (rand.float(f32) * 2.0 - 1.0) * bound;
    }
    try t.copyToDevice(std.mem.sliceAsBytes(host));
}

fn initUniformBias(t: *Tensor, fan_in: u32) !void {
    const n = t.numElements();
    var host = try t.allocator.alloc(f32, n);
    defer t.allocator.free(host);

    const bound = 1.0 / @sqrt(@as(f32, @floatFromInt(fan_in)));
    var prng = std.rand.DefaultPrng.init(0xBEEFCAFE + fan_in);
    const rand = prng.random();
    for (host) |*v| {
        v.* = (rand.float(f32) * 2.0 - 1.0) * bound;
    }
    try t.copyToDevice(std.mem.sliceAsBytes(host));
}
