const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const Linear = @import("linear.zig").Linear;
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const PRISM = struct {
    allocator: std.mem.Allocator,
    hidden_dim: u32,
    num_iters: u32,
    alpha: f32,
    conv_weight: Tensor,
    w_beta: []Linear,
    w_k: []Linear,
    w_p: []Linear,
    state: ?Tensor,
    shortconv_window: u32,
    saved_x: ?Tensor,
    saved_conv_out: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, cfg: config_mod.ModelConfig) !PRISM {
        var conv_weight = try Tensor.init(
            allocator,
            &[_]u32{ cfg.prism_shortconv_window, cfg.hidden_dim },
            .f32,
        );
        const n_conv = conv_weight.numElements();
        var conv_host = try allocator.alloc(f32, n_conv);
        defer allocator.free(conv_host);
        var prng = std.rand.DefaultPrng.init(0xABCD1234);
        const rand = prng.random();
        const std_dev = @sqrt(1.0 / @as(f32, @floatFromInt(cfg.prism_shortconv_window * cfg.hidden_dim)));
        for (conv_host) |*v| v.* = rand.floatNorm(f32) * std_dev;
        try conv_weight.copyToDevice(std.mem.sliceAsBytes(conv_host));
        try conv_weight.initGrad();

        var w_beta = try allocator.alloc(Linear, cfg.prism_num_iters);
        var w_k = try allocator.alloc(Linear, cfg.prism_num_iters);
        var w_p = try allocator.alloc(Linear, cfg.prism_num_iters);

        for (0..cfg.prism_num_iters) |i| {
            w_beta[i] = try Linear.init(allocator, cfg.hidden_dim, cfg.hidden_dim, false);
            w_k[i] = try Linear.init(allocator, cfg.hidden_dim, cfg.hidden_dim, false);
            w_p[i] = try Linear.init(allocator, cfg.hidden_dim, cfg.hidden_dim, false);
        }

        return PRISM{
            .allocator = allocator,
            .hidden_dim = cfg.hidden_dim,
            .num_iters = cfg.prism_num_iters,
            .alpha = cfg.prism_alpha,
            .conv_weight = conv_weight,
            .w_beta = w_beta,
            .w_k = w_k,
            .w_p = w_p,
            .state = null,
            .shortconv_window = cfg.prism_shortconv_window,
            .saved_x = null,
            .saved_conv_out = null,
        };
    }

    pub fn deinit(self: *PRISM) void {
        self.conv_weight.deinit();
        for (self.w_beta) |*w| w.deinit();
        for (self.w_k) |*w| w.deinit();
        for (self.w_p) |*w| w.deinit();
        self.allocator.free(self.w_beta);
        self.allocator.free(self.w_k);
        self.allocator.free(self.w_p);
        if (self.state) |*s| s.deinit();
        if (self.saved_x) |*s| s.deinit();
        if (self.saved_conv_out) |*s| s.deinit();
    }

    pub fn forward(self: *PRISM, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const batch_seq = x.numElements() / self.hidden_dim;

        var conv_out = try Tensor.init(allocator, x.shape(), .f32);
        c.launch_short_conv(
            @ptrCast(x.data_gpu),
            @ptrCast(self.conv_weight.data_gpu),
            @ptrCast(conv_out.data_gpu),
            1,
            @intCast(batch_seq),
            @intCast(self.hidden_dim),
            @intCast(self.shortconv_window),
            null,
        );

        if (self.state == null) {
            self.state = try Tensor.zeros(
                allocator,
                &[_]u32{ self.hidden_dim, self.hidden_dim },
                .f32,
            );
        }

        var beta_ptrs = try allocator.alloc(*anyopaque, self.num_iters);
        defer allocator.free(beta_ptrs);
        var k_ptrs = try allocator.alloc(*anyopaque, self.num_iters);
        defer allocator.free(k_ptrs);
        var delta_ptrs = try allocator.alloc(*anyopaque, self.num_iters);
        defer allocator.free(delta_ptrs);

        var iter_betas = try allocator.alloc(Tensor, self.num_iters);
        defer {
            for (iter_betas) |*t| t.deinit();
            allocator.free(iter_betas);
        }
        var iter_ks = try allocator.alloc(Tensor, self.num_iters);
        defer {
            for (iter_ks) |*t| t.deinit();
            allocator.free(iter_ks);
        }
        var iter_deltas = try allocator.alloc(Tensor, self.num_iters);
        defer {
            for (iter_deltas) |*t| t.deinit();
            allocator.free(iter_deltas);
        }

        for (0..self.num_iters) |i| {
            iter_betas[i] = try self.w_beta[i].forward(&conv_out, allocator);
            iter_ks[i] = try self.w_k[i].forward(&conv_out, allocator);

            var h_k = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.hidden_dim }, .f32);
            c.launch_outer_product(
                @ptrCast(self.state.?.data_gpu),
                @ptrCast(iter_ks[i].data_gpu),
                @ptrCast(h_k.data_gpu),
                @intCast(self.hidden_dim),
                @intCast(self.hidden_dim),
                @intCast(batch_seq),
                null,
            );
            iter_deltas[i] = try self.w_p[i].forward(&conv_out, allocator);
            c.launch_elementwise_sub(
                @ptrCast(iter_deltas[i].data_gpu),
                @ptrCast(h_k.data_gpu),
                @ptrCast(iter_deltas[i].data_gpu),
                @intCast(iter_deltas[i].numElements()),
                null,
            );
            h_k.deinit();

            beta_ptrs[i] = iter_betas[i].data_gpu.?;
            k_ptrs[i] = iter_ks[i].data_gpu.?;
            delta_ptrs[i] = iter_deltas[i].data_gpu.?;
        }

        c.launch_prism_state_update(
            @ptrCast(self.state.?.data_gpu),
            @ptrCast(beta_ptrs.ptr),
            @ptrCast(k_ptrs.ptr),
            @ptrCast(delta_ptrs.ptr),
            @intCast(self.num_iters),
            @intCast(self.hidden_dim),
            self.alpha,
            null,
        );

        if (self.saved_x) |*s| s.deinit();
        if (self.saved_conv_out) |*s| s.deinit();
        self.saved_x = try Tensor.init(allocator, x.shape(), .f32);
        try self.saved_x.?.copyFrom(x);
        self.saved_conv_out = conv_out;

        var readout = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.hidden_dim }, .f32);
        c.launch_outer_product(
            @ptrCast(self.state.?.data_gpu),
            @ptrCast(x.data_gpu),
            @ptrCast(readout.data_gpu),
            @intCast(self.hidden_dim),
            @intCast(self.hidden_dim),
            @intCast(batch_seq),
            null,
        );

        return readout;
    }
};
