        x_n3.deinit();

        if (self.saved_ffn_pre_gelu) |*s| s.deinit();
        self.saved_ffn_pre_gelu = try Tensor.init(allocator, ffn_up_out.shape(), .f32);
        try self.saved_ffn_pre_gelu.?.copyFrom(&ffn_up_out);

        c.launch_gelu(
            @ptrCast(ffn_up_out.data_gpu),
            @ptrCast(ffn_up_out.data_gpu),
            @intCast(ffn_up_out.numElements()),
            null,
        );

        if (self.saved_ffn_mid) |*s| s.deinit();
        self.saved_ffn_mid = try Tensor.init(allocator, ffn_up_out.shape(), .f32);
        try self.saved_ffn_mid.?.copyFrom(&ffn_up_out);

        var ffn_out = try self.ffn_down.forward(&ffn_up_out, allocator);
        ffn_up_out.deinit();

        c.launch_elementwise_add(
            @ptrCast(x.data_gpu),
            @ptrCast(ffn_out.data_gpu),
            @ptrCast(ffn_out.data_gpu),
            @intCast(ffn_out.numElements()),
            null,
        );

        return ffn_out;
    }

    pub fn backward(self: *TransformerBlock, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        var grad_ffn_mid = try self.ffn_down.backward(self.saved_ffn_mid.?, grad_out, allocator);
        defer grad_ffn_mid.deinit();

        var grad_ffn_pre_gelu = try Tensor.zeros(allocator, self.saved_ffn_pre_gelu.?.shape(), .f32);
        c.launch_gelu_backward(
            @ptrCast(self.saved_ffn_pre_gelu.?.data_gpu),
            @ptrCast(grad_ffn_mid.data_gpu),
            @ptrCast(grad_ffn_pre_gelu.data_gpu),
            @intCast(grad_ffn_pre_gelu.numElements()),
            null,
        );

        var grad_x_n3 = try self.ffn_up.backward(self.saved_x_normed3.?, &grad_ffn_pre_gelu, allocator);
        grad_ffn_pre_gelu.deinit();

        var grad_before_n3 = try self.norm3.backward(self.saved_x_normed3.?, &grad_x_n3, allocator);
        grad_x_n3.deinit();

        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_before_n3.data_gpu),
            @ptrCast(grad_before_n3.data_gpu),
            @intCast(grad_before_n3.numElements()),
            null,
        );

        var grad_x_n2 = try self.norm2.backward(self.saved_x_normed2.?, &grad_before_n3, allocator);
        grad_before_n3.deinit();

        var grad_before_n2 = try self.efla.backward(&grad_x_n2, allocator);
        grad_x_n2.deinit();

        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_before_n2.data_gpu),
            @ptrCast(grad_before_n2.data_gpu),
            @intCast(grad_before_n2.numElements()),
            null,
        );

        var grad_x_n1 = try self.norm1.backward(self.saved_x_normed1.?, &grad_before_n2, allocator);
        grad_before_n2.deinit();

        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_x_n1.data_gpu),
            @ptrCast(grad_x_n1.data_gpu),
            @intCast(grad_x_n1.numElements()),
            null,
        );

        return grad_x_n1;
    }
