const std = @import("std");
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("nccl.h");
});

pub const DistributedRuntime = struct {
    allocator: std.mem.Allocator,
    rank: u32,
    world_size: u32,
    gpu_ids: []u32,
    nccl_comms: []c.ncclComm_t,
    streams: []c.cudaStream_t,
