const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const RMSNorm = struct {
    allocator: std.mem.Allocator,
    hidden: u32,
    eps: f32,
    weight: Tensor,
    saved_rms: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, hidden: u32, eps: f32) !RMSNorm {
        var weight = try Tensor.init(allocator, &[_]u32{hidden}, .f32);
        var host = try allocator.alloc(f32, hidden);
        defer allocator.free(host);
        for (host) |*v| v.* = 1.0;
        try weight.copyToDevice(std.mem.sliceAsBytes(host));
        try weight.initGrad();

        return RMSNorm{
            .allocator = allocator,
            .hidden = hidden,
            .eps = eps,
            .weight = weight,
            .saved_rms = null,
        };
    }

    pub fn deinit(self: *RMSNorm) void {
        self.weight.deinit();
        if (self.saved_rms) |*s| s.deinit();
    }

    pub fn forward(self: *RMSNorm, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const total = x.numElements();
        const batch_seq = total / self.hidden;

        if (self.saved_rms == null) {
            self.saved_rms = try Tensor.init(allocator, &[_]u32{@intCast(batch_seq)}, .f32);
        } else if (self.saved_rms.?.dims[0] != @as(u32, @intCast(batch_seq))) {
            self.saved_rms.?.deinit();
            self.saved_rms = try Tensor.init(allocator, &[_]u32{@intCast(batch_seq)}, .f32);
        }

        var out = try Tensor.init(allocator, x.shape(), .f32);

        c.launch_rms_norm(
            @ptrCast(x.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(out.data_gpu),
            @ptrCast(self.saved_rms.?.data_gpu),
            1,
            @intCast(batch_seq),
            @intCast(self.hidden),
            self.eps,
            null,
        );
        return out;
    }

    pub fn backward(self: *RMSNorm, x: *Tensor, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const total = x.numElements();
        const batch_seq = total / self.hidden;
        var grad_x = try Tensor.zeros(allocator, x.shape(), .f32);

        c.launch_rms_norm_backward(
            @ptrCast(x.data_gpu),
            @ptrCast(grad_out.data_gpu),
            @ptrCast(self.weight.data_gpu),
            @ptrCast(self.saved_rms.?.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @ptrCast(self.weight.grad.?.data_gpu),
            1,
            @intCast(batch_seq),
            @intCast(self.hidden),
            self.eps,
            null,
        );
