const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const Embedding = struct {
    allocator: std.mem.Allocator,
    vocab_size: u32,
    hidden_dim: u32,
    weight: Tensor,

    pub fn init(allocator: std.mem.Allocator, vocab_size: u32, hidden_dim: u32) !Embedding {
        var weight = try Tensor.init(allocator, &[_]u32{ vocab_size, hidden_dim }, .f32);
        const n = weight.numElements();
        var host = try allocator.alloc(f32, n);
        defer allocator.free(host);

        const std_dev = @sqrt(1.0 / @as(f32, @floatFromInt(hidden_dim)));
        var prng = std.rand.DefaultPrng.init(0x12345678);
        const rand = prng.random();
        for (host) |*v| {
            v.* = rand.floatNorm(f32) * std_dev;
        }
        try weight.copyToDevice(std.mem.sliceAsBytes(host));
        try weight.initGrad();

        return Embedding{
            .allocator = allocator,
            .vocab_size = vocab_size,
            .hidden_dim = hidden_dim,
            .weight = weight,
        };
    }

    pub fn deinit(self: *Embedding) void {
        self.weight.deinit();
    }

    pub fn forward(self: *Embedding, ids: []const u32, allocator: std.mem.Allocator) !Tensor {
        const seq_len = ids.len;
        var ids_gpu: ?*anyopaque = null;
        const nb = seq_len * @sizeOf(u32);
        _ = c.cudaMalloc(&ids_gpu, nb);
        defer _ = c.cudaFree(ids_gpu);
        _ = c.cudaMemcpy(ids_gpu, ids.ptr, nb, c.cudaMemcpyHostToDevice);

        var out = try Tensor.init(allocator, &[_]u32{ @intCast(seq_len), self.hidden_dim }, .f32);
        c.launch_embedding_lookup(
            @ptrCast(self.weight.data_gpu),
            @ptrCast(ids_gpu),
            @ptrCast(out.data_gpu),
            @intCast(seq_len),
            @intCast(self.hidden_dim),
            null,
        );
        return out;
    }
};
