const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const Linear = @import("linear.zig").Linear;
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const EFLA = struct {
    allocator: std.mem.Allocator,
    hidden_dim: u32,
    num_heads: u32,
    head_dim: u32,
    chunk_size: u32,
    w_q: Linear,
    w_k: Linear,
    w_v: Linear,
    w_out: Linear,
    beta: Tensor,
    state: ?Tensor,
    saved_lambda: ?Tensor,
    saved_c: ?Tensor,
    saved_k: ?Tensor,
    saved_v: ?Tensor,
    saved_x: ?Tensor,
    saved_efla_out: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, cfg: config_mod.ModelConfig) !EFLA {
        var w_q = try Linear.init(allocator, cfg.hidden_dim, cfg.num_heads * cfg.head_dim, false);
        var w_k = try Linear.init(allocator, cfg.hidden_dim, cfg.num_heads * cfg.head_dim, false);
        var w_v = try Linear.init(allocator, cfg.hidden_dim, cfg.num_heads * cfg.head_dim, false);
        var w_out = try Linear.init(allocator, cfg.num_heads * cfg.head_dim, cfg.hidden_dim, false);

        var beta = try Tensor.init(allocator, &[_]u32{cfg.num_heads}, .f32);
        var beta_host = try allocator.alloc(f32, cfg.num_heads);
        defer allocator.free(beta_host);
        for (beta_host) |*v| v.* = cfg.efla_beta_init;
        try beta.copyToDevice(std.mem.sliceAsBytes(beta_host));
        if (cfg.efla_beta_learnable) try beta.initGrad();

        return EFLA{
            .allocator = allocator,
            .hidden_dim = cfg.hidden_dim,
            .num_heads = cfg.num_heads,
            .head_dim = cfg.head_dim,
            .chunk_size = cfg.efla_chunk_size,
            .w_q = w_q,
            .w_k = w_k,
            .w_v = w_v,
            .w_out = w_out,
            .beta = beta,
            .state = null,
            .saved_lambda = null,
            .saved_c = null,
            .saved_k = null,
            .saved_v = null,
            .saved_x = null,
            .saved_efla_out = null,
        };
    }

    pub fn deinit(self: *EFLA) void {
        self.w_q.deinit();
        self.w_k.deinit();
        self.w_v.deinit();
        self.w_out.deinit();
        self.beta.deinit();
        if (self.state) |*s| s.deinit();
        if (self.saved_lambda) |*s| s.deinit();
        if (self.saved_c) |*s| s.deinit();
        if (self.saved_k) |*s| s.deinit();
        if (self.saved_v) |*s| s.deinit();
        if (self.saved_x) |*s| s.deinit();
        if (self.saved_efla_out) |*s| s.deinit();
    }

    pub fn resetState(self: *EFLA, batch_size: u32, allocator: std.mem.Allocator) !void {
        if (self.state) |*s| s.deinit();
        self.state = try Tensor.zeros(
            allocator,
            &[_]u32{ batch_size, self.num_heads, self.head_dim, self.head_dim },
            .f32,
        );
    }

    pub fn forward(self: *EFLA, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const batch_seq = x.numElements() / self.hidden_dim;

        var k = try self.w_k.forward(x, allocator);
        var v = try self.w_v.forward(x, allocator);

        const state_size = self.num_heads * self.head_dim * self.head_dim;
        if (self.state == null) {
            self.state = try Tensor.zeros(allocator, &[_]u32{ 1, state_size }, .f32);
        }

        var efla_out = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.num_heads * self.head_dim }, .f32);

        var lambda_buf = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.num_heads }, .f32);
        var c_buf = try Tensor.init(allocator, &[_]u32{ @intCast(batch_seq), self.num_heads }, .f32);

        c.launch_efla_forward(
            @ptrCast(k.data_gpu),
            @ptrCast(v.data_gpu),
            @ptrCast(self.beta.data_gpu),
            self.state.?.data_gpu,
            @ptrCast(efla_out.data_gpu),
            @ptrCast(lambda_buf.data_gpu),
            @ptrCast(c_buf.data_gpu),
            1,
            @intCast(batch_seq),
            @intCast(self.num_heads),
            @intCast(self.head_dim),
            @intCast(self.chunk_size),
            null,
        );

        if (self.saved_lambda) |*s| s.deinit();
        if (self.saved_c) |*s| s.deinit();
        if (self.saved_k) |*s| s.deinit();
        if (self.saved_v) |*s| s.deinit();
        if (self.saved_x) |*s| s.deinit();
        if (self.saved_efla_out) |*s| s.deinit();

        self.saved_lambda = lambda_buf;
        self.saved_c = c_buf;
        self.saved_k = k;
        self.saved_v = v;
        self.saved_x = try Tensor.init(allocator, x.shape(), .f32);
        try self.saved_x.?.copyFrom(x);
        self.saved_efla_out = try Tensor.init(allocator, efla_out.shape(), .f32);
        try self.saved_efla_out.?.copyFrom(&efla_out);

        var out = try self.w_out.forward(&efla_out, allocator);
        efla_out.deinit();
        return out;
    }

    pub fn backward(self: *EFLA, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        const batch_seq = grad_out.numElements() / self.hidden_dim;

        var grad_efla = try self.w_out.backward(self.saved_efla_out.?, grad_out, allocator);
        defer grad_efla.deinit();

        var grad_k = try Tensor.zeros(allocator, self.saved_k.?.shape(), .f32);
        var grad_v = try Tensor.zeros(allocator, self.saved_v.?.shape(), .f32);

        c.launch_efla_backward(
            @ptrCast(self.saved_k.?.data_gpu),
            @ptrCast(self.saved_v.?.data_gpu),
            @ptrCast(self.beta.data_gpu),
            @ptrCast(self.saved_c.?.data_gpu),
            @ptrCast(self.saved_lambda.?.data_gpu),
            @ptrCast(grad_efla.data_gpu),
            @ptrCast(grad_k.data_gpu),
            @ptrCast(grad_v.data_gpu),
            @ptrCast(self.beta.grad.?.data_gpu),
            self.state.?.data_gpu,
            1,
            @intCast(batch_seq),
            @intCast(self.num_heads),
            @intCast(self.head_dim),
            null,
        );

        var grad_x_k = try self.w_k.backward(self.saved_x.?, &grad_k, allocator);
        defer grad_x_k.deinit();
        var grad_x_v = try self.w_v.backward(self.saved_x.?, &grad_v, allocator);
        defer grad_x_v.deinit();

        grad_k.deinit();
        grad_v.deinit();

        var grad_x = try Tensor.zeros(allocator, self.saved_x.?.shape(), .f32);

        c.launch_elementwise_add(
            @ptrCast(grad_x_k.data_gpu),
            @ptrCast(grad_x_v.data_gpu),
            @ptrCast(grad_x.data_gpu),
            @intCast(grad_x.numElements()),
            null,
        );

        return grad_x;
    }
};
