const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const Linear = @import("../nn/linear.zig").Linear;
const RMSNorm = @import("../nn/rms_norm.zig").RMSNorm;
const EFLA = @import("../nn/efla.zig").EFLA;
const PRISM = @import("../nn/prism.zig").PRISM;
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const TransformerBlock = struct {
    allocator: std.mem.Allocator,
    norm1: RMSNorm,
    norm2: RMSNorm,
    norm3: RMSNorm,
    efla: EFLA,
    prism: PRISM,
    ffn_up: Linear,
    ffn_down: Linear,
    hidden_dim: u32,
    ffn_dim: u32,
    saved_x: ?Tensor,
    saved_x_normed1: ?Tensor,
    saved_x_normed2: ?Tensor,
    saved_x_normed3: ?Tensor,
    saved_efla_residual: ?Tensor,
    saved_prism_residual: ?Tensor,
    saved_ffn_pre_gelu: ?Tensor,
    saved_ffn_mid: ?Tensor,

    pub fn init(allocator: std.mem.Allocator, cfg: config_mod.ModelConfig) !TransformerBlock {
        return TransformerBlock{
            .allocator = allocator,
            .norm1 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps),
            .norm2 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps),
            .norm3 = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps),
            .efla = try EFLA.init(allocator, cfg),
            .prism = try PRISM.init(allocator, cfg),
            .ffn_up = try Linear.init(allocator, cfg.hidden_dim, cfg.ffn_dim, false),
            .ffn_down = try Linear.init(allocator, cfg.ffn_dim, cfg.hidden_dim, false),
            .hidden_dim = cfg.hidden_dim,
            .ffn_dim = cfg.ffn_dim,
            .saved_x = null,
            .saved_x_normed1 = null,
            .saved_x_normed2 = null,
            .saved_x_normed3 = null,
            .saved_efla_residual = null,
            .saved_prism_residual = null,
            .saved_ffn_pre_gelu = null,
            .saved_ffn_mid = null,
        };
    }

    pub fn deinit(self: *TransformerBlock) void {
        self.norm1.deinit();
        self.norm2.deinit();
        self.norm3.deinit();
        self.efla.deinit();
        self.prism.deinit();
        self.ffn_up.deinit();
        self.ffn_down.deinit();
        if (self.saved_x) |*s| s.deinit();
        if (self.saved_x_normed1) |*s| s.deinit();
        if (self.saved_x_normed2) |*s| s.deinit();
        if (self.saved_x_normed3) |*s| s.deinit();
        if (self.saved_efla_residual) |*s| s.deinit();
        if (self.saved_prism_residual) |*s| s.deinit();
        if (self.saved_ffn_pre_gelu) |*s| s.deinit();
        if (self.saved_ffn_mid) |*s| s.deinit();
    }

    pub fn forward(self: *TransformerBlock, x: *Tensor, allocator: std.mem.Allocator) !Tensor {
        if (self.saved_x) |*s| s.deinit();
        self.saved_x = try Tensor.init(allocator, x.shape(), .f32);
        try self.saved_x.?.copyFrom(x);

        var x_n1 = try self.norm1.forward(x, allocator);
        if (self.saved_x_normed1) |*s| s.deinit();
        self.saved_x_normed1 = try Tensor.init(allocator, x_n1.shape(), .f32);
        try self.saved_x_normed1.?.copyFrom(&x_n1);

        var efla_out = try self.efla.forward(&x_n1, allocator);
        x_n1.deinit();

        var x_after_efla = try Tensor.init(allocator, efla_out.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(x.data_gpu),
            @ptrCast(efla_out.data_gpu),
            @ptrCast(x_after_efla.data_gpu),
            @intCast(efla_out.numElements()),
            null,
        );
        efla_out.deinit();

        if (self.saved_efla_residual) |*s| s.deinit();
        self.saved_efla_residual = try Tensor.init(allocator, x_after_efla.shape(), .f32);
        try self.saved_efla_residual.?.copyFrom(&x_after_efla);

        var x_n2 = try self.norm2.forward(&x_after_efla, allocator);
        x_after_efla.deinit();

        if (self.saved_x_normed2) |*s| s.deinit();
        self.saved_x_normed2 = try Tensor.init(allocator, x_n2.shape(), .f32);
        try self.saved_x_normed2.?.copyFrom(&x_n2);

        var prism_out = try self.prism.forward(&x_n2, allocator);
        x_n2.deinit();

        var x_after_prism = try Tensor.init(allocator, prism_out.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(self.saved_efla_residual.?.data_gpu),
            @ptrCast(prism_out.data_gpu),
            @ptrCast(x_after_prism.data_gpu),
            @intCast(prism_out.numElements()),
            null,
        );
        prism_out.deinit();

        if (self.saved_prism_residual) |*s| s.deinit();
        self.saved_prism_residual = try Tensor.init(allocator, x_after_prism.shape(), .f32);
        try self.saved_prism_residual.?.copyFrom(&x_after_prism);

        var x_n3 = try self.norm3.forward(&x_after_prism, allocator);
        x_after_prism.deinit();

        if (self.saved_x_normed3) |*s| s.deinit();
        self.saved_x_normed3 = try Tensor.init(allocator, x_n3.shape(), .f32);
        try self.saved_x_normed3.?.copyFrom(&x_n3);

        var ffn_up_out = try self.ffn_up.forward(&x_n3, allocator);
        x_n3.deinit();

        if (self.saved_ffn_pre_gelu) |*s| s.deinit();
        self.saved_ffn_pre_gelu = try Tensor.init(allocator, ffn_up_out.shape(), .f32);
        try self.saved_ffn_pre_gelu.?.copyFrom(&ffn_up_out);

        c.launch_gelu(
            @ptrCast(ffn_up_out.data_gpu),
            @ptrCast(ffn_up_out.data_gpu),
            @intCast(ffn_up_out.numElements()),
            null,
        );

        if (self.saved_ffn_mid) |*s| s.deinit();
        self.saved_ffn_mid = try Tensor.init(allocator, ffn_up_out.shape(), .f32);
        try self.saved_ffn_mid.?.copyFrom(&ffn_up_out);

        var ffn_out = try self.ffn_down.forward(&ffn_up_out, allocator);
        ffn_up_out.deinit();

        var out = try Tensor.init(allocator, ffn_out.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(self.saved_prism_residual.?.data_gpu),
            @ptrCast(ffn_out.data_gpu),
            @ptrCast(out.data_gpu),
            @intCast(ffn_out.numElements()),
            null,
        );
        ffn_out.deinit();

        return out;
    }

    pub fn backward(self: *TransformerBlock, grad_out: *Tensor, allocator: std.mem.Allocator) !Tensor {
        var grad_ffn_mid = try self.ffn_down.backward(self.saved_ffn_mid.?, grad_out, allocator);
        defer grad_ffn_mid.deinit();

        var grad_ffn_pre_gelu = try Tensor.zeros(allocator, self.saved_ffn_pre_gelu.?.shape(), .f32);
        c.launch_gelu_backward(
            @ptrCast(self.saved_ffn_pre_gelu.?.data_gpu),
            @ptrCast(grad_ffn_mid.data_gpu),
            @ptrCast(grad_ffn_pre_gelu.data_gpu),
            @intCast(grad_ffn_pre_gelu.numElements()),
            null,
        );

        var grad_x_n3 = try self.ffn_up.backward(self.saved_x_normed3.?, &grad_ffn_pre_gelu, allocator);
        grad_ffn_pre_gelu.deinit();

        var grad_before_n3 = try self.norm3.backward(self.saved_x_normed3.?, &grad_x_n3, allocator);
        grad_x_n3.deinit();

        var grad_after_prism = try Tensor.init(allocator, grad_before_n3.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_before_n3.data_gpu),
            @ptrCast(grad_after_prism.data_gpu),
            @intCast(grad_before_n3.numElements()),
            null,
        );
        grad_before_n3.deinit();

        var grad_x_n2 = try self.norm2.backward(self.saved_x_normed2.?, &grad_after_prism, allocator);
        grad_after_prism.deinit();

        var grad_before_n2 = try self.efla.backward(&grad_x_n2, allocator);
        grad_x_n2.deinit();

        var grad_after_efla = try Tensor.init(allocator, grad_before_n2.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_before_n2.data_gpu),
            @ptrCast(grad_after_efla.data_gpu),
            @intCast(grad_before_n2.numElements()),
            null,
        );
        grad_before_n2.deinit();

        var grad_x_n1 = try self.norm1.backward(self.saved_x_normed1.?, &grad_after_efla, allocator);
        grad_after_efla.deinit();

        var grad_input = try Tensor.init(allocator, grad_x_n1.shape(), .f32);
        c.launch_elementwise_add(
            @ptrCast(grad_out.data_gpu),
            @ptrCast(grad_x_n1.data_gpu),
            @ptrCast(grad_input.data_gpu),
            @intCast(grad_x_n1.numElements()),
            null,
        );
        grad_x_n1.deinit();

        return grad_input;
    }
};
