const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const Embedding = @import("../nn/embedding.zig").Embedding;
const RMSNorm = @import("../nn/rms_norm.zig").RMSNorm;
const TransformerBlock = @import("block.zig").TransformerBlock;
const config_mod = @import("../util/config.zig");
const distributed = @import("../runtime/distributed.zig");
const lion_mod = @import("../optim/lion.zig");
const muon_mod = @import("../optim/muon.zig");
const state_shard_mod = @import("../optim/state_shard.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("kernels.h");
});

pub const ForwardResult = struct {
    loss: f32,
    tokens_processed: u64,
    grad_norm: f32,
};

pub const LanguageModel = struct {
    allocator: std.mem.Allocator,
    cfg: config_mod.ModelConfig,
    dist: *distributed.DistributedRuntime,
    embed: Embedding,
    blocks: []TransformerBlock,
    final_norm: RMSNorm,
    saved_hidden_states: []?Tensor,

    pub fn init(
        allocator: std.mem.Allocator,
        cfg: config_mod.ModelConfig,
        dist: *distributed.DistributedRuntime,
    ) !LanguageModel {
        var embed = try Embedding.init(allocator, cfg.vocab_size, cfg.hidden_dim);

        var blocks = try allocator.alloc(TransformerBlock, cfg.num_layers);
        for (blocks) |*blk| {
            blk.* = try TransformerBlock.init(allocator, cfg);
        }

        var final_norm = try RMSNorm.init(allocator, cfg.hidden_dim, cfg.rms_norm_eps);

        var saved_hidden_states = try allocator.alloc(?Tensor, cfg.num_layers + 1);
        for (saved_hidden_states) |*s| s.* = null;

        return LanguageModel{
            .allocator = allocator,
            .cfg = cfg,
            .dist = dist,
            .embed = embed,
            .blocks = blocks,
            .final_norm = final_norm,
            .saved_hidden_states = saved_hidden_states,
        };
    }

    pub fn deinit(self: *LanguageModel) void {
        self.embed.deinit();
        for (self.blocks) |*blk| blk.deinit();
        self.allocator.free(self.blocks);
        self.final_norm.deinit();
        for (self.saved_hidden_states) |*s| {
            if (s.*) |*t| t.deinit();
        }
        self.allocator.free(self.saved_hidden_states);
    }

    pub fn forward(
        self: *LanguageModel,
        tokens: []const u32,
        seq_len: u32,
        allocator: std.mem.Allocator,
    ) !Tensor {
        var h = try self.embed.forward(tokens, allocator);

        if (self.saved_hidden_states[0]) |*s| s.deinit();
        self.saved_hidden_states[0] = try Tensor.init(allocator, h.shape(), .f32);
        try self.saved_hidden_states[0].?.copyFrom(&h);

        for (self.blocks, 0..) |*blk, i| {
            var h_new = try blk.forward(&h, allocator);
            h.deinit();
            h = h_new;

            if (self.saved_hidden_states[i + 1]) |*s| s.deinit();
            self.saved_hidden_states[i + 1] = try Tensor.init(allocator, h.shape(), .f32);
            try self.saved_hidden_states[i + 1].?.copyFrom(&h);
        }

        var h_normed = try self.final_norm.forward(&h, allocator);
        h.deinit();

        var logits = try Tensor.init(allocator, &[_]u32{ seq_len, self.cfg.vocab_size }, .f32);

        c.launch_tied_lm_head(
            @ptrCast(h_normed.data_gpu),
            @ptrCast(self.embed.weight.data_gpu),
            @ptrCast(logits.data_gpu),
            @intCast(seq_len),
            @intCast(self.cfg.vocab_size),
            @intCast(self.cfg.hidden_dim),
            null,
        );

        h_normed.deinit();
        return logits;
    }

    pub fn forwardBackward(
        self: *LanguageModel,
        allocator: std.mem.Allocator,
        tokens: []const u32,
        targets: []const u32,
        label_smoothing: f32,
    ) !ForwardResult {
        const seq_len: u32 = @intCast(tokens.len);

        var logits = try self.forward(tokens, seq_len, allocator);
        defer logits.deinit();

        var targets_gpu: ?*anyopaque = null;
        const tgt_nb = targets.len * @sizeOf(u32);
        _ = c.cudaMalloc(&targets_gpu, tgt_nb);
        _ = c.cudaMemcpy(targets_gpu, targets.ptr, tgt_nb, c.cudaMemcpyHostToDevice);
        defer _ = c.cudaFree(targets_gpu);

        var grad_logits = try Tensor.zeros(allocator, logits.shape(), .f32);
        defer grad_logits.deinit();

        var loss_tensor = try Tensor.zeros(allocator, &[_]u32{1}, .f32);
        defer loss_tensor.deinit();

        c.launch_cross_entropy_loss(
            @ptrCast(logits.data_gpu),
            @ptrCast(targets_gpu),
            @ptrCast(grad_logits.data_gpu),
            @ptrCast(loss_tensor.data_gpu),
            @intCast(seq_len),
            @intCast(self.cfg.vocab_size),
            label_smoothing,
            null,
        );

        var loss_host: f32 = 0.0;
        _ = c.cudaMemcpy(&loss_host, loss_tensor.data_gpu, @sizeOf(f32), c.cudaMemcpyDeviceToHost);

        var grad_h_normed = try Tensor.zeros(allocator, &[_]u32{ seq_len, self.cfg.hidden_dim }, .f32);
        defer grad_h_normed.deinit();

        c.launch_tied_lm_head_backward(
            @ptrCast(grad_logits.data_gpu),
            @ptrCast(self.embed.weight.data_gpu),
            @ptrCast(grad_h_normed.data_gpu),
            @ptrCast(self.embed.weight.grad.?.data_gpu),
            @intCast(seq_len),
            @intCast(self.cfg.vocab_size),
            @intCast(self.cfg.hidden_dim),
            null,
        );

        var grad_h = try self.final_norm.backward(
            self.saved_hidden_states[self.cfg.num_layers].?,
            &grad_h_normed,
            allocator,
        );

        var layer_idx: usize = self.cfg.num_layers;
        while (layer_idx > 0) {
            layer_idx -= 1;
            var grad_h_new = try self.blocks[layer_idx].backward(&grad_h, allocator);
            grad_h.deinit();
            grad_h = grad_h_new;
        }
        grad_h.deinit();

        const grad_norm = try self.computeGradNorm();

        return ForwardResult{
            .loss = loss_host,
            .tokens_processed = seq_len,
            .grad_norm = grad_norm,
        };
    }

    pub fn computeGradNorm(self: *LanguageModel) !f32 {
        var total_sq: f64 = 0.0;

        if (self.embed.weight.grad) |g| {
            const embed_grad_data = try g.copyToHost(self.allocator);
            defer self.allocator.free(embed_grad_data);
            const embed_floats = std.mem.bytesAsSlice(f32, embed_grad_data);
            for (embed_floats) |v| total_sq += @floatCast(v * v);
        }

        for (self.blocks) |*blk| {
            if (blk.ffn_up.weight.grad) |g| {
                const data = try g.copyToHost(self.allocator);
                defer self.allocator.free(data);
                const floats = std.mem.bytesAsSlice(f32, data);
                for (floats) |v| total_sq += @floatCast(v * v);
            }
            if (blk.ffn_down.weight.grad) |g| {
                const data = try g.copyToHost(self.allocator);
                defer self.allocator.free(data);
                const floats = std.mem.bytesAsSlice(f32, data);
                for (floats) |v| total_sq += @floatCast(v * v);
            }
        }

        return @floatCast(@sqrt(total_sq));
    }

    pub fn clipGradients(self: *LanguageModel, max_norm: f32) !void {
        const grad_norm = try self.computeGradNorm();
        if (grad_norm <= max_norm) return;
        const scale = max_norm / grad_norm;

        if (self.embed.weight.grad) |g| {
            c.launch_scale_inplace(
                @ptrCast(g.data_gpu),
                @intCast(g.numElements()),
                scale,
                null,
            );
        }

        for (self.blocks) |*blk| {
            if (blk.ffn_up.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
            if (blk.ffn_down.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
            if (blk.efla.w_q.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
            if (blk.efla.w_k.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
            if (blk.efla.w_v.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
            if (blk.efla.w_out.weight.grad) |g| {
                c.launch_scale_inplace(@ptrCast(g.data_gpu), @intCast(g.numElements()), scale, null);
            }
        }
    }

    pub fn optimizerStep(
        self: *LanguageModel,
        allocator: std.mem.Allocator,
        lion: *lion_mod.Lion,
        muon: *muon_mod.Muon,
        shard: *state_shard_mod.OptimizerStateShard,
        dist: *distributed.DistributedRuntime,
    ) !void {
        _ = allocator;
        _ = shard;
        _ = dist;

        try lion.step(&self.embed.weight, self.embed.weight.grad.?);

        for (self.blocks) |*blk| {
            try lion.step(&blk.ffn_up.weight, blk.ffn_up.weight.grad.?);
            try lion.step(&blk.ffn_down.weight, blk.ffn_down.weight.grad.?);
            try muon.step(&blk.efla.w_q.weight, blk.efla.w_q.weight.grad.?);
            try muon.step(&blk.efla.w_k.weight, blk.efla.w_k.weight.grad.?);
            try muon.step(&blk.efla.w_v.weight, blk.efla.w_v.weight.grad.?);
            try muon.step(&blk.efla.w_out.weight, blk.efla.w_out.weight.grad.?);
            for (blk.prism.w_beta) |*w| try muon.step(&w.weight, w.weight.grad.?);
            for (blk.prism.w_k) |*w| try muon.step(&w.weight, w.weight.grad.?);
            for (blk.prism.w_p) |*w| try muon.step(&w.weight, w.weight.grad.?);
        }

        try self.zeroAllGrads();
    }

    pub fn zeroAllGrads(self: *LanguageModel) !void {
        try self.embed.weight.zeroGrad();
        for (self.blocks) |*blk| {
            try blk.ffn_up.weight.zeroGrad();
            try blk.ffn_down.weight.zeroGrad();
            try blk.norm1.weight.zeroGrad();
            try blk.norm2.weight.zeroGrad();
            try blk.norm3.weight.zeroGrad();
            try blk.efla.w_q.weight.zeroGrad();
            try blk.efla.w_k.weight.zeroGrad();
            try blk.efla.w_v.weight.zeroGrad();
            try blk.efla.w_out.weight.zeroGrad();
            try blk.efla.beta.zeroGrad();
            try blk.prism.conv_weight.zeroGrad();
            for (blk.prism.w_beta) |*w| try w.weight.zeroGrad();
            for (blk.prism.w_k) |*w| try w.weight.zeroGrad();
            for (blk.prism.w_p) |*w| try w.weight.zeroGrad();
        }
        try self.final_norm.weight.zeroGrad();
    }
};
