const std = @import("std");
const config_mod = @import("../util/config.zig");

const c = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("nccl.h");
});

pub const DistributedRuntime = struct {
    allocator: std.mem.Allocator,
    rank: u32,
    world_size: u32,
    gpu_ids: []u32,
    nccl_comms: []c.ncclComm_t,
    streams: []c.cudaStream_t,
    initialized: bool,

    pub fn init(
        allocator: std.mem.Allocator,
        gpu_ids: []const u32,
        cluster_cfg: config_mod.ClusterConfig,
    ) !DistributedRuntime {
        _ = cluster_cfg;

        const world_size = gpu_ids.len;
        const gpu_ids_copy = try allocator.dupe(u32, gpu_ids);

        const rank_env = std.posix.getenv("RANK");
        const rank: u32 = if (rank_env) |r| std.fmt.parseInt(u32, r, 10) catch 0 else 0;

        const nccl_comms = try allocator.alloc(c.ncclComm_t, world_size);
        const streams = try allocator.alloc(c.cudaStream_t, world_size);

        _ = c.cudaSetDevice(@intCast(gpu_ids[rank % world_size]));

        for (0..world_size) |i| {
            _ = c.cudaStreamCreate(&streams[i]);
        }

        var uid: c.ncclUniqueId = undefined;
        if (rank == 0) {
            _ = c.ncclGetUniqueId(&uid);
        }

        _ = c.ncclCommInitRank(&nccl_comms[rank], @intCast(world_size), uid, @intCast(rank));

        return DistributedRuntime{
            .allocator = allocator,
            .rank = rank,
            .world_size = @intCast(world_size),
            .gpu_ids = gpu_ids_copy,
            .nccl_comms = nccl_comms,
            .streams = streams,
            .initialized = true,
        };
    }

    pub fn deinit(self: *DistributedRuntime) void {
        if (self.initialized) {
            for (self.nccl_comms) |comm| {
                _ = c.ncclCommDestroy(comm);
            }
            for (self.streams) |stream| {
                _ = c.cudaStreamDestroy(stream);
            }
        }
        self.allocator.free(self.gpu_ids);
        self.allocator.free(self.nccl_comms);
        self.allocator.free(self.streams);
    }

    pub fn allReduceSum(self: *DistributedRuntime, tensor_ptr: *anyopaque, count: usize) !void {
        _ = c.ncclAllReduce(
            tensor_ptr,
            tensor_ptr,
            count,
            c.ncclFloat,
            c.ncclSum,
            self.nccl_comms[self.rank],
            self.streams[self.rank],
        );
        _ = c.cudaStreamSynchronize(self.streams[self.rank]);
    }

    pub fn broadcastFrom(self: *DistributedRuntime, tensor_ptr: *anyopaque, count: usize, root: u32) !void {
        _ = c.ncclBcast(
            tensor_ptr,
            count,
            c.ncclFloat,
            @intCast(root),
            self.nccl_comms[self.rank],
            self.streams[self.rank],
        );
        _ = c.cudaStreamSynchronize(self.streams[self.rank]);
    }

    pub fn synchronizeBarrier(self: *DistributedRuntime) !void {
        _ = c.cudaStreamSynchronize(self.streams[self.rank]);
        _ = c.cudaDeviceSynchronize();
    }

    pub fn getStream(self: *DistributedRuntime) c.cudaStream_t {
        return self.streams[self.rank];
    }
};
