        return Muon{
            .allocator = allocator,
            .lr = lr,
            .momentum = momentum,
            .ns_iters = ns_iters,
            .momentum_map = std.AutoHashMap(usize, Tensor).init(allocator),
            .step_count = 0,
        };
    }

    pub fn deinit(self: *Muon) void {
        var it = self.momentum_map.valueIterator();
