const std = @import("std");
const Tensor = @import("../tensor/tensor.zig").Tensor;
const shard_util = @import("../tensor/shard.zig");

pub const OptimizerStateShard = struct {
    allocator: std.mem.Allocator,
    rank: u32,
    world_size: u32,
    param_shards: std.AutoHashMap(usize, Tensor),
    grad_shards: std.AutoHashMap(usize, Tensor),
    momentum_shards: std.AutoHashMap(usize, Tensor),
    variance_shards: std.AutoHashMap(usize, Tensor),

    pub fn init(allocator: std.mem.Allocator, rank: u32, world_size: u32) !OptimizerStateShard {
        return OptimizerStateShard{
            .allocator = allocator,
            .rank = rank,
            .world_size = world_size,
            .param_shards = std.AutoHashMap(usize, Tensor).init(allocator),
            .grad_shards = std.AutoHashMap(usize, Tensor).init(allocator),
            .momentum_shards = std.AutoHashMap(usize, Tensor).init(allocator),
            .variance_shards = std.AutoHashMap(usize, Tensor).init(allocator),
        };
    }

    pub fn deinit(self: *OptimizerStateShard) void {
        var it1 = self.param_shards.valueIterator();
        while (it1.next()) |v| v.deinit();
        self.param_shards.deinit();

        var it2 = self.grad_shards.valueIterator();
        while (it2.next()) |v| v.deinit();
        self.grad_shards.deinit();

        var it3 = self.momentum_shards.valueIterator();
        while (it3.next()) |v| v.deinit();
        self.momentum_shards.deinit();

        var it4 = self.variance_shards.valueIterator();
        while (it4.next()) |v| v.deinit();
        self.variance_shards.deinit();
    }

    pub fn getOrCreateParamShard(self: *OptimizerStateShard, param: *Tensor) !*Tensor {
        const key = @intFromPtr(param.data_gpu);
        const gop = try self.param_shards.getOrPut(key);
        if (!gop.found_existing) {
            const full_size = param.numElements();
            const shard_size = shard_util.shardedSize(@intCast(full_size), self.rank, self.world_size);
            gop.value_ptr.* = try Tensor.zeros(self.allocator, &[_]u32{shard_size}, .f32);
        }
        return gop.value_ptr;
    }

    pub fn getOrCreateGradShard(self: *OptimizerStateShard, param: *Tensor) !*Tensor {
        const key = @intFromPtr(param.data_gpu);
        const gop = try self.grad_shards.getOrPut(key);
        if (!gop.found_existing) {
            const full_size = param.numElements();
            const shard_size = shard_util.shardedSize(@intCast(full_size), self.rank, self.world_size);
            gop.value_ptr.* = try Tensor.zeros(self.allocator, &[_]u32{shard_size}, .f32);
        }
        return gop.value_ptr;
    }

    pub fn getOrCreateMomentumShard(self: *OptimizerStateShard, param: *Tensor) !*Tensor {
        const key = @intFromPtr(param.data_gpu);
        const gop = try self.momentum_shards.getOrPut(key);
        if (!gop.found_existing) {
            const full_size = param.numElements();
            const shard_size = shard_util.shardedSize(@intCast(full_size), self.rank, self.world_size);
