const std = @import("std");
const bpe_mod = @import("bpe.zig");

pub const Tokenizer = struct {
    allocator: std.mem.Allocator,
    bpe: bpe_mod.BPEModel,
    bos_id: u32,
    eos_id: u32,
    pad_id: u32,
    unk_id: u32,

    pub fn loadModel(allocator: std.mem.Allocator, path: []const u8) !Tokenizer {
        const bpe = try bpe_mod.BPEModel.load(allocator, path);
        return Tokenizer{
            .allocator = allocator,
            .bpe = bpe,
            .bos_id = 1,
            .eos_id = 2,
            .pad_id = 0,
            .unk_id = 3,
        };
    }

    pub fn deinit(self: *Tokenizer) void {
        self.bpe.deinit();
    }

    pub fn encode(self: *Tokenizer, text: []const u8, allocator: std.mem.Allocator) ![]u32 {
        return self.bpe.encode(text, allocator);
    }

    pub fn decode(self: *Tokenizer, ids: []const u32, allocator: std.mem.Allocator) ![]u8 {
        return self.bpe.decode(ids, allocator);
    }

    pub fn encodeFile(self: *Tokenizer, input_path: []const u8, output_path: []const u8) !void {
        const input_file = try std.fs.openFileAbsolute(input_path, .{});
        defer input_file.close();
        const text = try input_file.readToEndAlloc(self.allocator, 1 << 30);
        defer self.allocator.free(text);

        const ids = try self.encode(text, self.allocator);
        defer self.allocator.free(ids);

        const out_file = try std.fs.createFileAbsolute(output_path, .{});
        defer out_file.close();

        const header = [_]u32{ 0x544F4B00, @intCast(ids.len) };
        try out_file.writeAll(std.mem.sliceAsBytes(&header));
        try out_file.writeAll(std.mem.sliceAsBytes(ids));
    }

    pub fn decodeFile(self: *Tokenizer, input_path: []const u8, output_path: []const u8) !void {
        const input_file = try std.fs.openFileAbsolute(input_path, .{});
        defer input_file.close();

        var header = [_]u32{ 0, 0 };
        _ = try input_file.readAll(std.mem.sliceAsBytes(&header));

        const num_tokens = header[1];
        const ids = try self.allocator.alloc(u32, num_tokens);
        defer self.allocator.free(ids);
        _ = try input_file.readAll(std.mem.sliceAsBytes(ids));

        const text = try self.decode(ids, self.allocator);
        defer self.allocator.free(text);

        const out_file = try std.fs.createFileAbsolute(output_path, .{});
        defer out_file.close();
        try out_file.writeAll(text);
    }
};
