const std = @import("std");
const hash_util = @import("../util/hash.zig");

pub fn writeManifest(allocator: std.mem.Allocator, dir: []const u8) !void {
    var dir_handle = try std.fs.openDirAbsolute(dir, .{ .iterate = true });
    defer dir_handle.close();

    var entries = std.ArrayList([]u8).init(allocator);
    defer {
        for (entries.items) |e| allocator.free(e);
        entries.deinit();
    }

    var it = dir_handle.iterate();
    while (try it.next()) |entry| {
        if (entry.kind != .file) continue;
        if (std.mem.eql(u8, entry.name, "manifest.sha256")) continue;
        try entries.append(try allocator.dupe(u8, entry.name));
    }

    std.mem.sort([]u8, entries.items, {}, struct {
        fn lessThan(_: void, a: []u8, b: []u8) bool {
            return std.mem.lessThan(u8, a, b);
        }
    }.lessThan);

    var manifest_buf = std.ArrayList(u8).init(allocator);
    defer manifest_buf.deinit();

    for (entries.items) |name| {
        const fpath = try std.fmt.allocPrint(allocator, "{s}/{s}", .{ dir, name });
        defer allocator.free(fpath);
        var hash_bytes
